def refine_verdict(
    claim_text: str,
    support: list[str],
    contradictions: list[str],
    prosecutor_case: list[str],
    defender_case: list[str],
    deterministic_verdict: str
) -> VerdictDraft by llm(temperature=0.2);

sem refine_verdict = """
Refine a startup-assumption verdict without changing the deterministic status
unless the evidence summary clearly demands it. Return a compact verdict with
status, confidence, rationale, and next_action.
""";

walker WitnessFinder {
    has support: list[str] = [];
    has contradictions: list[str] = [];

    obj __specs__ {
        static has methods: list[str] = ["post"];
        static has auth: bool = False;
    }

    can inspect with Claim entry {
        for ev in [<--][?:Evidence] {
            if ev.stance == "support" {
                self.support.append(ev.text);
            } elif ev.stance == "contradict" {
                self.contradictions.append(ev.text);
            }
        }

        report {
            "claim": here.text,
            "support": self.support,
            "contradictions": self.contradictions
        };
    }
}

walker Prosecutor {
    has arguments: list[str] = [];

    obj __specs__ {
        static has methods: list[str] = ["post"];
        static has auth: bool = False;
    }

    can prosecute with Claim entry {
        evidence = [<--][?:Evidence];
        contradictions = [ev for ev in evidence if ev.stance == "contradict"];
        support = [ev for ev in evidence if ev.stance == "support"];

        if len(evidence) == 0 {
            self.arguments.append("No evidence is connected to this claim.");
        }

        if len(contradictions) > 0 {
            self.arguments.append("Contradicting evidence challenges the claim.");
        }

        if len(contradictions) > len(support) {
            self.arguments.append("Contradictions currently outnumber support.");
        }

        report self.arguments;
    }
}

walker Defender {
    has arguments: list[str] = [];

    obj __specs__ {
        static has methods: list[str] = ["post"];
        static has auth: bool = False;
    }

    can defend with Claim entry {
        evidence = [<--][?:Evidence];
        support = [ev for ev in evidence if ev.stance == "support"];

        if len(support) > 0 {
            self.arguments.append("The claim has supporting evidence.");
        } else {
            self.arguments.append("The claim may still be useful as a hypothesis.");
        }

        report self.arguments;
    }
}

walker Judge {
    has prosecutor_case: list[str] = [];
    has defender_case: list[str] = [];

    obj __specs__ {
        static has methods: list[str] = ["post"];
        static has auth: bool = False;
    }

    can judge with Claim entry {
        evidence = [<--][?:Evidence];
        support = [ev for ev in evidence if ev.stance == "support"];
        contradictions = [ev for ev in evidence if ev.stance == "contradict"];

        verdict = "uncertain";
        confidence = 45;

        if len(evidence) == 0 {
            verdict = "needs_human";
            confidence = 24;
        } elif len(contradictions) > len(support) {
            verdict = "rejected";
            confidence = 70;
        } elif len(support) > len(contradictions) {
            verdict = "accepted";
            confidence = 74;
        }

        here.status = verdict;
        here.confidence = confidence;

        report {
            "claim": here.text,
            "status": verdict,
            "confidence": confidence,
            "support_count": len(support),
            "contradiction_count": len(contradictions)
        };
    }
}

walker Bailiff {
    obj __specs__ {
        static has methods: list[str] = ["post"];
        static has auth: bool = False;
    }

    can create_action with Claim entry {
        if here.status != "accepted" {
            task = Task(
                title=f"Validate assumption: {here.text}",
                reason="Court verdict requires follow-up evidence."
            );
            here +>: CreatesTask :+> task;
            report {"task": task.title, "claim": here.text};
        }
    }
}

"""CivicMesh — entry point.

The `cl { ... }` block is the client UI shell — it just imports `ClientApp`
from `frontend.cl.jac` and renders it. The real UI lives there.

Server-side walker registration is handled by the companion variant file
`app.sv.jac`. Jac's variant loader merges that file into the server build
automatically, while the client build skips it entirely — so the walker
classes never leak into the browser JS bundle.
"""

