"""Async implementations for the ClientApp root component."""

# DEMO_USER_ID and DEMO_USER_PASSWORD are defined as globs in
# frontend.cl.jac so the production client bundle resolves them.

impl ClientApp.initAuth -> None {
    # Auth bootstrap that survives Factory rebuilds on free HF Spaces.
    #
    # Two compounding failure modes we have to handle:
    #
    # 1) On a fresh container, demo_user does not exist yet. The old
    #    code did login-first / signup-on-failure, but
    #    `ok = await jacLogin(...)` returns an object `{success: false, ...}`
    #    on failure — and `if not ok` is `false` for a truthy object,
    #    so the signup branch never fired. Fix: signup first (idempotent
    #    — 409 if user exists, fine), then login, then verify with
    #    `jacIsLoggedIn()` (the only reliable truthiness signal because
    #    it checks the actual stored token).
    #
    # 2) When the container restarts but the browser keeps the old token
    #    in localStorage, jacIsLoggedIn() returns true but the token
    #    references a user that no longer exists. Walker calls then 500
    #    with "User not found". Fix: probe /user/me with the stored
    #    token; if it 401s, clear it so the signup+login below runs.
    #
    # The runtime's __normalizeIdentity wraps the username string into
    # the correct flat {type, value} shape the server expects, so plain
    # string args to jacSignup/jacLogin are correct — verified via curl
    # against the deployed openapi.json schema.

    is_authed = False;

    # Stale-token check
    if jacIsLoggedIn() {
        try {
            probe = await fetch("/user/me", {
                "headers": {"Authorization": "Bearer " + localStorage.getItem("jac_token")}
            });
            if probe.status >= 400 {
                localStorage.removeItem("jac_token");
            }
        } except Exception as _ex {
            localStorage.removeItem("jac_token");
        }
    }

    if jacIsLoggedIn() {
        is_authed = True;
    } else {
        try {
            await jacSignup(DEMO_USER_ID, DEMO_USER_PASSWORD);
        } except Exception as _ex {}
        try {
            await jacLogin(DEMO_USER_ID, DEMO_USER_PASSWORD);
        } except Exception as _ex {}
        is_authed = jacIsLoggedIn();
    }

    if is_authed {
        user_id = DEMO_USER_ID;
        try {
            await root spawn SeedWalker(user_id=DEMO_USER_ID);
        } except Exception as _ex {}
    }
}

impl ClientApp.loadSession -> None {
    # Defensive gate — loadSession should only run after initAuth has
    # confirmed jacIsLoggedIn(). On a stale browser session whose token
    # has been revoked by a Factory rebuild, the cached app state will
    # still think we're authed; spawning walkers without a fresh login
    # gives the same "User not found" 500s. We re-run the same direct-
    # fetch auth flow as initAuth (see comments above) rather than the
    # @jac/runtime helpers, which silently no-op on shape mismatch.
    # Same stale-token probe as initAuth — guards against the case where
    # a Factory rebuild deleted the user but the browser still has the
    # old token. Without this, walker spawns below 500 with "User not
    # found" and we never recover.
    if jacIsLoggedIn() {
        try {
            probe = await fetch("/user/me", {
                "headers": {"Authorization": "Bearer " + localStorage.getItem("jac_token")}
            });
            if probe.status >= 400 {
                localStorage.removeItem("jac_token");
            }
        } except Exception as _ex {
            localStorage.removeItem("jac_token");
        }
    }

    if not jacIsLoggedIn() {
        try { await jacSignup(DEMO_USER_ID, DEMO_USER_PASSWORD); } except Exception as _ex {}
        try { await jacLogin(DEMO_USER_ID, DEMO_USER_PASSWORD); } except Exception as _ex {}
        if not jacIsLoggedIn() {
            session_data = {};
            return;
        }
        user_id = DEMO_USER_ID;
    }

    # Always re-run SeedWalker on session load so an already-authed user
    # whose root predates the demo-apps feature still picks them up on
    # next refresh. SeedWalker is idempotent — duplicate resource and
    # leads_to insertion is guarded; demo apps only seed when the
    # PersonNode has zero existing ApplicationNodes attached.
    try {
        await root spawn SeedWalker(user_id=user_id);
    } except Exception as _ex {}

    try {
        result = await root spawn MemoryWalker(
            user_id=user_id,
            mode="read_session"
        );
        raw = result.reports[0] if result.reports else None;
        if raw {
            session_data = raw;
        } else {
            session_data = {};
        }
    } except Exception as e {
        session_data = {};
    }
}

impl ClientApp.startApp -> None {
    # CTA from the landing page hides it and routes the user to the chat tab.
    # Auth runs on mount (initAuth in `with entry`). If it hasn't finished
    # yet, ChatPane's sendMessage will retry — don't block the UI here.
    show_landing = False;
    active_tab = "chat";
}

impl ClientApp.pushWalkerEvent(events: list) -> None {
    # Receives the FULL accumulated events list each call (not a delta).
    # This sidesteps React closure staleness when sendMessage fires many
    # updates in one synchronous burst — each call sets walker_events to
    # the full known list, so the last winner contains everything.
    walker_events = events;
}

impl ClientApp.navTab(tab_id: str, label: str) -> JsxElement {
    is_active = active_tab == tab_id;
    return
        <button
            onClick={lambda _e: MouseEvent { active_tab = tab_id; }}
            style={{
                "padding": "7px 14px",
                "background": ("#FFE500" if is_active else "transparent"),
                "color": ("#0A0A0A" if is_active else "rgba(255,255,255,0.55)"),
                "border": "none",
                "borderRadius": "8px",
                "fontSize": "13px",
                "fontWeight": ("600" if is_active else "500"),
                "cursor": "pointer",
                "transition": "all 0.2s ease",
                "display": "flex",
                "alignItems": "center",
                "gap": "7px"
            }}
        >
            {tabIcon(tab_id, is_active)}
            {label}
        </button>;
}

impl ClientApp.tabIcon(tab_id: str, is_active: bool) -> JsxElement {
    # Inline SVG traced icons — no emoji, no image files. Stroke color
    # tracks the active state so the active tab's black on yellow stays
    # visible while inactive tabs use a faded white.
    stroke = "#0A0A0A" if is_active else "rgba(255,255,255,0.7)";
    if tab_id == "chat" {
        # Speech bubble outline with a tail
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <path
                    d="M4 6.5 C 4 5.1 5.1 4 6.5 4 L 17.5 4 C 18.9 4 20 5.1 20 6.5 L 20 14 C 20 15.4 18.9 16.5 17.5 16.5 L 11 16.5 L 7 20 L 7 16.5 L 6.5 16.5 C 5.1 16.5 4 15.4 4 14 Z"
                    stroke={stroke}
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                />
            </svg>;
    }
    if tab_id == "graph" {
        # Three connected nodes
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <circle cx="6" cy="6" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <circle cx="18" cy="8" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <circle cx="12" cy="18" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <path d="M8 7.5 L 15.5 8 M 17 10.5 L 13 15.5 M 7.5 8 L 10.5 16" stroke={stroke} strokeWidth="1.5" strokeLinecap="round"/>
            </svg>;
    }
    if tab_id == "plan" {
        # Checklist (rectangle + three rows + a check)
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <rect x="4" y="3" width="16" height="18" rx="2" stroke={stroke} strokeWidth="1.8"/>
                <path d="M8 8 L 10 10 L 13 7" stroke={stroke} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                <path d="M8 14 L 16 14 M 8 17.5 L 14 17.5" stroke={stroke} strokeWidth="1.6" strokeLinecap="round"/>
            </svg>;
    }
    if tab_id == "telemetry" {
        # Bar chart, three ascending bars
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <rect x="4" y="13" width="3.5" height="7" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
                <rect x="10.25" y="9" width="3.5" height="11" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
                <rect x="16.5" y="5" width="3.5" height="15" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
            </svg>;
    }
    if tab_id == "impact" {
        # Heart outline — anchors the Impact tab to its outcomes story
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <path
                    d="M12 20 C 7 16 3 13 3 9 C 3 6 5.5 4 8 4 C 10 4 11.5 5 12 7 C 12.5 5 14 4 16 4 C 18.5 4 21 6 21 9 C 21 13 17 16 12 20 Z"
                    stroke={stroke}
                    strokeWidth="1.6"
                    strokeLinejoin="round"
                />
            </svg>;
    }
    return <span/>;
}

impl ClientApp.togglePalette -> None {
    palette_open = (not palette_open);
    palette_query = "";
    palette_idx = 0;
}

impl ClientApp.runPaletteAction(action: Any) -> None {
    # Single dispatch site so the keyboard handler and the mouse click both
    # route through one place. Closes the palette after every action so the
    # user gets back to the work surface immediately.
    kind = str(action["kind"]);
    payload = str(action["payload"]);
    if kind == "tab" {
        active_tab = payload;
    } elif kind == "replay" {
        # Cheap "replay" — toggle the active tab to graph; the GraphViz
        # component's own Replay button is the canonical trigger and is
        # right there once you land.
        active_tab = "graph";
    } elif kind == "docs" {
        # Open the jac-scale auto-generated OpenAPI page in a new tab.
        # `window.open` is a JS builtin; jac compiles the bare name through.
        try {
            window.open("http://localhost:8001/docs", "_blank");
        } except Exception as _ex {}
    } elif kind == "reset" {
        # Reset the live walker_events buffer so the graph + telemetry
        # tabs show a clean slate without forcing a full page reload.
        walker_events = [];
    }
    palette_open = False;
    palette_query = "";
    palette_idx = 0;
}

impl ClientApp.renderPaletteItem(action: Any, idx: int, sel: int) -> JsxElement {
    label = str(action["label"]);
    is_selected = idx == sel;
    return
        <div
            key={label}
            onClick={lambda _e: MouseEvent { runPaletteAction(action); }}
            onMouseEnter={lambda _e: MouseEvent { palette_idx = idx; }}
            style={{
                "padding": "10px 14px",
                "borderRadius": "8px",
                "background": ("rgba(255,229,0,0.1)" if is_selected else "transparent"),
                "border": ("0.5px solid rgba(255,229,0,0.35)" if is_selected else "0.5px solid transparent"),
                "color": ("#FFE500" if is_selected else "rgba(255,255,255,0.8)"),
                "fontSize": "13px",
                "cursor": "pointer",
                "display": "flex",
                "alignItems": "center",
                "gap": "10px",
                "transition": "all 0.12s ease"
            }}
        >
            <span style={{
                "fontFamily": "ui-monospace, monospace",
                "fontSize": "10px",
                "color": ("#FFE500" if is_selected else "rgba(255,255,255,0.3)"),
                "minWidth": "16px"
            }}>
                {"›"}
            </span>
            <span style={{"flex": "1"}}>{label}</span>
            {is_selected and <span style={{
                "fontSize": "9px",
                "fontFamily": "ui-monospace, monospace",
                "padding": "2px 6px",
                "background": "rgba(255,229,0,0.15)",
                "border": "0.5px solid rgba(255,229,0,0.3)",
                "borderRadius": "4px",
                "color": "#FFE500",
                "letterSpacing": "0.04em"
            }}>
                ENTER
            </span>}
        </div>;
}

impl ClientApp.renderPalette -> JsxElement {
    # Fuzzy substring filter — case-insensitive, no scoring beyond "contains".
    # Keeps the implementation tiny and predictable; the action list is short
    # enough that a fancier ranking would be lost on the user.
    q = palette_query.lower().strip();
    filtered: list = [];
    for a in palette_actions {
        lbl_lower = str(a["label"]).lower();
        if (not q) or (q in lbl_lower) {
            filtered = filtered + [a];
        }
    }
    sel = palette_idx;
    if sel >= len(filtered) and len(filtered) > 0 {
        sel = 0;
    }

    return
        <div
            onClick={lambda _e: MouseEvent { togglePalette(); }}
            style={{
                "position": "fixed",
                "inset": "0",
                "zIndex": "1000",
                "background": "rgba(5,5,8,0.65)",
                "backdropFilter": "blur(8px)",
                "display": "flex",
                "alignItems": "flex-start",
                "justifyContent": "center",
                "paddingTop": "14vh"
            }}
        >
            <div
                onClick={lambda e: MouseEvent { e.stopPropagation(); }}
                style={{
                    "width": "560px",
                    "maxWidth": "92vw",
                    "background": "linear-gradient(180deg, rgba(20,20,24,0.95), rgba(12,12,16,0.95))",
                    "border": "0.5px solid rgba(255,255,255,0.12)",
                    "borderRadius": "14px",
                    "boxShadow": "0 32px 72px -20px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,229,0,0.06)",
                    "overflow": "hidden"
                }}
            >
                <div style={{"padding": "14px 16px 10px", "borderBottom": "0.5px solid rgba(255,255,255,0.06)", "display": "flex", "alignItems": "center", "gap": "10px"}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" style={{"flexShrink": "0"}}>
                        <circle cx="11" cy="11" r="6.5" stroke="rgba(255,229,0,0.6)" strokeWidth="1.6"/>
                        <path d="M16 16 L 20 20" stroke="rgba(255,229,0,0.6)" strokeWidth="1.6" strokeLinecap="round"/>
                    </svg>
                    <input
                        value={palette_query}
                        onChange={lambda e: ChangeEvent { palette_query = e.target.value; palette_idx = 0; }}
                        onKeyDown={lambda e: KeyboardEvent {
                            if e.key == "ArrowDown" {
                                e.preventDefault();
                                if palette_idx + 1 < len(filtered) { palette_idx = palette_idx + 1; }
                            } elif e.key == "ArrowUp" {
                                e.preventDefault();
                                if palette_idx > 0 { palette_idx = palette_idx - 1; }
                            } elif e.key == "Enter" {
                                e.preventDefault();
                                if len(filtered) > 0 {
                                    runPaletteAction(filtered[sel]);
                                }
                            } elif e.key == "Escape" {
                                togglePalette();
                            }
                        }}
                        placeholder="Type a command — tabs, replay, docs, reset..."
                        autoFocus={True}
                        style={{
                            "flex": "1",
                            "background": "transparent",
                            "border": "none",
                            "outline": "none",
                            "color": "#FFFFFF",
                            "fontSize": "14px",
                            "fontFamily": "system-ui, sans-serif"
                        }}
                    />
                    <span style={{
                        "fontSize": "10px",
                        "color": "rgba(255,255,255,0.35)",
                        "fontFamily": "ui-monospace, monospace",
                        "padding": "3px 7px",
                        "background": "rgba(255,255,255,0.04)",
                        "border": "0.5px solid rgba(255,255,255,0.1)",
                        "borderRadius": "5px"
                    }}>
                        ESC
                    </span>
                </div>
                <div style={{"padding": "8px", "maxHeight": "50vh", "overflowY": "auto", "display": "flex", "flexDirection": "column", "gap": "2px"}}>
                    {(len(filtered) == 0) and <div style={{"padding": "20px", "textAlign": "center", "fontSize": "12px", "color": "rgba(255,255,255,0.4)"}}>
                        No matching commands.
                    </div>}
                    {[renderPaletteItem(filtered[i], i, sel) for i in range(len(filtered))]}
                </div>
                <div style={{
                    "padding": "8px 16px",
                    "borderTop": "0.5px solid rgba(255,255,255,0.06)",
                    "display": "flex",
                    "alignItems": "center",
                    "gap": "12px",
                    "fontSize": "10px",
                    "color": "rgba(255,255,255,0.4)",
                    "fontFamily": "ui-monospace, monospace"
                }}>
                    <span>↑↓ navigate</span>
                    <span>↵ run</span>
                    <span>esc close</span>
                    <span style={{"flex": "1"}}/>
                    <span>{str(len(filtered)) + " action" + ("" if len(filtered) == 1 else "s")}</span>
                </div>
            </div>
        </div>;
}

"""CivicMesh typed edge definitions.

Edges carry the relationship semantics that walkers traverse. Direction matters:
the source-to-target arrow in the comments is the directed edge as it exists
in the graph, and walkers follow that direction unless reversed explicitly.
"""

# PersonNode -> NeedNode
edge has_need {}
sem has_need is "A PersonNode currently has this NeedNode open. Created when extract_need_profile() lifts a need from conversation. Persists until the underlying need is resolved.";

# NeedNode -> ResourceNode
edge eligible_for {}
sem eligible_for is "A NeedNode could be fulfilled by this ResourceNode. Created by the EligibilityWalker after check_eligibility() returns is_eligible=true.";

# ResourceNode -> EligibilityRuleNode
edge governed_by {}
sem governed_by is "A ResourceNode is governed by this EligibilityRuleNode. Static schema relationship installed by the seed loader; not modified at runtime.";

# EligibilityRuleNode -> FormNode
edge requires_form {}
sem requires_form is "An EligibilityRuleNode requires this FormNode to be completed. Static schema relationship installed by the seed loader.";

# PersonNode -> ApplicationNode
edge applied_to {}
sem applied_to is "A PersonNode has filed (or started) an application captured in this ApplicationNode. Persists across sessions so returning users see their history.";

# ResourceNode -> ResourceNode
# Carries the real-world "progression" between civic resources. Used by
# PathfinderWalker to discover multi-step escape paths when a user has
# zero direct eligibility matches. The payload fields ground each hop in
# real bureaucratic transitions so the LLM-rendered chain reads as
# concrete advice ("submit Form X, then your priority bumps for Y") rather
# than generic links.
edge leads_to {
    has transition_reason: str = "",
        typical_days: int = 30,
        difficulty: str = "moderate";
}

sem leads_to is "Real-world progression between civic resources. Pre-seeded with curated transitions (Emergency Shelter -> Transitional Housing -> Section 8 priority). PathfinderWalker walks these edges with BFS to surface 2-3 step escape paths when EligibilityWalker has no direct match.";
sem leads_to.transition_reason is "One-line plain-language explanation of why one resource leads to the next (e.g. 'Emergency Shelter intake auto-creates a Section 8 priority application'). Surfaced verbatim to the user as the path step's caption.";
sem leads_to.typical_days is "Realistic number of days the transition takes in practice. Used to estimate total path duration for the user.";
sem leads_to.difficulty is "Perceived friction of making this hop. One of: 'easy' (auto-flow), 'moderate' (paperwork), 'hard' (legal advocate recommended).";

# PersonNode -> SessionInsight
edge reflected_on {}
sem reflected_on is "Connects a PersonNode to a SessionInsight written after each chat turn. IntakeWalker traverses these edges on the next turn to read the agent's own recent self-critique and prepend it as context — Reflexion-style self-improvement via pure graph memory, no external retrieval store.";

"""CivicMesh graph node definitions.

All six node types in the schema, plus a semstring on every field.
The semstrings are what the byLLM router uses to ground walker reasoning
when it inspects the graph at runtime - keep them dense and unambiguous.
"""

node PersonNode {
    has user_id: str = "",
        language: str = "en",
        location_zip: str = "",
        income_bracket: str = "",
        family_size: int = 1,
        preferred_contact: str = "phone",
        created_at: str = "";
}

sem PersonNode is "A vulnerable individual seeking assistance. Root of every session subgraph. Carries the profile fields used by EligibilityWalker to filter ResourceNodes.";
sem PersonNode.user_id is "Stable identifier tied to the authenticated session. Used to look up a returning user's prior ApplicationNodes.";
sem PersonNode.language is "ISO 639-1 language code (e.g. en, es, fr, vi) detected from the user's first message. All walker responses must be produced in this language.";
sem PersonNode.location_zip is "US zip code (5 digits) or city name. Used for proximity matching against ResourceNode.address and for state/county residency rules on EligibilityRuleNode.";
sem PersonNode.income_bracket is "Annual household income range. One of: '0-15k', '15k-30k', '30k-50k', '50k+'. Compared against EligibilityRuleNode.income_limit_annual during eligibility scoring.";
sem PersonNode.family_size is "Number of people in the household, including the user. Compared against EligibilityRuleNode.min_family_size and used to size SNAP/WIC/housing allocations.";
sem PersonNode.preferred_contact is "How the person wants follow-up to happen. One of: 'phone', 'email', 'in-person', 'online'. Drives which ResourceNode contact field the ActionPlan should surface first.";
sem PersonNode.created_at is "ISO 8601 timestamp of when this PersonNode was first created. Used to distinguish first-time vs returning users in session summaries.";

node NeedNode {
    has category: str = "",
        urgency: str = "within_weeks",
        details: str = "",
        created_at: str = "";
}

sem NeedNode is "A discrete need expressed by the PersonNode during conversation. One PersonNode can have many NeedNodes - e.g. housing + food + healthcare simultaneously.";
sem NeedNode.category is "Top-level domain of the need. One of: 'housing', 'food', 'healthcare', 'legal'. Must match ResourceNode.category exactly so EligibilityWalker can join the two sets.";
sem NeedNode.urgency is "How quickly the user needs the resource. One of: 'immediate' (homeless tonight, no food today, crisis), 'within_days' (eviction notice, prescription out), 'within_weeks' (long-term housing search, ongoing benefits). Drives ordering in ActionPlan.";
sem NeedNode.details is "Free-form description in the user's own words. Preserved verbatim for the LLM to pick up nuance the categorical fields lose - e.g. 'I have a service dog' or 'I am undocumented'.";
sem NeedNode.created_at is "ISO 8601 timestamp when the need was first surfaced in conversation. Lets the system track which needs are still open vs already routed.";

node ResourceNode {
    has agency_name: str = "",
        category: str = "",
        capacity: str = "open",
        languages_supported: list[str] = [],
        contact_phone: str = "",
        contact_email: str = "",
        address: str = "",
        online_url: str = "",
        description: str = "";
}

sem ResourceNode is "A real-world agency, program, or service that can fulfill a NeedNode. Connected to EligibilityRuleNode via governed_by, and to NeedNode via eligible_for after matching.";
sem ResourceNode.agency_name is "Official name of the agency or program (e.g. 'Section 8 Housing Choice Voucher', 'Catholic Charities Food Pantry'). Acts as a natural primary key - the seed loader treats it as unique.";
sem ResourceNode.category is "Domain of service provided. One of: 'housing', 'food', 'healthcare', 'legal'. Must match NeedNode.category for the resource to be considered.";
sem ResourceNode.capacity is "Current intake status. One of: 'open' (accepting now), 'waitlist' (apply but expect delay), 'closed' (do not refer). The router demotes 'closed' to escalation paths only.";
sem ResourceNode.languages_supported is "List of ISO 639-1 codes the agency can serve. PersonNode.language must appear here, or the ActionPlan must include an interpreter referral.";
sem ResourceNode.contact_phone is "Primary phone number (digits and standard punctuation). Preferred entry-point for users with preferred_contact='phone'.";
sem ResourceNode.contact_email is "Public intake email address. Empty string when the agency does not publish one.";
sem ResourceNode.address is "Street address including city, state, zip. Used for proximity ranking against PersonNode.location_zip.";
sem ResourceNode.online_url is "Public-facing intake URL or program page. The ActionPlan deep-links to this for users with preferred_contact='online'.";
sem ResourceNode.description is "One-paragraph summary of what the resource provides, in plain language. The LLM uses this to explain choices to the user.";

node EligibilityRuleNode {
    has rule_id: str = "",
        income_limit_annual: int = 0,
        residency_requirement: str = "none",
        min_family_size: int = 0,
        citizenship_required: bool = False,
        age_min: int = 0,
        age_max: int = 0,
        exceptions: str = "",
        criteria_summary: str = "",
        # Outcome-learning fields. MemoryWalker updates these whenever
        # an ApplicationNode this rule gated transitions to approved or
        # denied. EligibilityWalker reads prior_success_rate as a
        # prior on the LLM's match_score so the graph genuinely learns
        # from real outcomes.
        prior_success_rate: float = 0.5,
        prior_attempts: int = 0,
        prior_approvals: int = 0;
}

sem EligibilityRuleNode is "The structured eligibility criteria for a ResourceNode. Read by check_eligibility() to score how well a PersonNode's profile matches.";
sem EligibilityRuleNode.rule_id is "Stable identifier for this rule, typically '<agency_slug>-rule'. Used so multiple resources can share or reference the same rule without duplication.";
sem EligibilityRuleNode.income_limit_annual is "Maximum allowed annual household income in USD. A value of 0 means there is no income limit. Compared against the upper bound of PersonNode.income_bracket.";
sem EligibilityRuleNode.residency_requirement is "Geographic scope required for eligibility. One of: 'state', 'county', 'city', 'none'. Matched against PersonNode.location_zip.";
sem EligibilityRuleNode.min_family_size is "Minimum number of household members required. 0 means no minimum. Some programs (e.g. family shelters) require >= 2.";
sem EligibilityRuleNode.citizenship_required is "True if the program legally requires US citizenship or specific immigration status. False for programs that serve everyone regardless of status (food banks, ERs, many legal aid clinics).";
sem EligibilityRuleNode.age_min is "Minimum applicant age in years. 0 means no minimum. Used by youth/senior-specific programs.";
sem EligibilityRuleNode.age_max is "Maximum applicant age in years. 0 means no maximum. Used by youth-only programs.";
sem EligibilityRuleNode.exceptions is "Free-form description of edge cases, waivers, and special populations the rule treats differently. The LLM consults this for borderline matches before declaring ineligibility.";
sem EligibilityRuleNode.criteria_summary is "Human-readable one-sentence summary of the rule, suitable for LLM prompts and user-facing explanations. The primary surface check_eligibility() reads.";
sem EligibilityRuleNode.prior_success_rate is "Bayesian-style success prior in [0, 1]. Starts at 0.5 (uninformative). MemoryWalker updates it whenever an ApplicationNode this rule gated transitions to approved or denied. EligibilityWalker weights LLM match_scores by this prior so the system tracks real-world outcomes over time, not just static rules.";
sem EligibilityRuleNode.prior_attempts is "Total count of ApplicationNodes that reached approved/denied status against this rule. Used as the denominator for prior_success_rate.";
sem EligibilityRuleNode.prior_approvals is "Count of those attempts that ended in approved. Numerator for prior_success_rate. Persists across sessions because the graph itself persists.";

# SessionInsight — Reflexion-style self-reflection persisted in the graph.
# After every chat turn, CritiqueWalker computes a quality score from the
# walker chain telemetry (no LLM call) and writes one of these. Future
# IntakeWalker turns read the last few back as context-prefix so the agent
# literally learns from its own past performance.
node SessionInsight {
    has session_id: str = "",
        ts: str = "",
        walkers_fired: list[str] = [],
        llm_calls_est: int = 0,
        escalated: bool = False,
        pathfinder_used: bool = False,
        navigation_used: bool = False,
        eligible_count: int = 0,
        quality_score: int = 50,
        headline: str = "",
        user_prompt_snippet: str = "";
}

sem SessionInsight is "Agent self-reflection record. Written by CritiqueWalker after each chat turn — pure graph mutation, no LLM call. Future IntakeWalker turns read the last few to prepend as context so the agent learns from its own past sessions without external memory infrastructure. Reflexion in pure Jac.";
sem SessionInsight.session_id is "Stable identifier for the chat turn. Timestamp-based; lets the client deduplicate when multiple insights for the same turn would otherwise stack.";
sem SessionInsight.ts is "ISO 8601 timestamp the insight was written. Used by Telemetry's rolling-trend chart and by IntakeWalker's recency-weighted lookback.";
sem SessionInsight.walkers_fired is "Distinct list of walker names that produced events during this turn. Drives the quality_score formula and surfaces in the Telemetry self-reflection panel.";
sem SessionInsight.llm_calls_est is "Estimated number of byllm calls this turn made. Heuristic: 1 intake + N eligibility candidates + (1 navigation OR 1 escalation) + translation. Lets the Telemetry tab compute rolling free-tier budget burn.";
sem SessionInsight.escalated is "True if the chain routed through EscalationWalker — a session-quality penalty. Demo loop: if escalation keeps firing on the same user, the agent should improve its NeedProfile extraction next turn.";
sem SessionInsight.pathfinder_used is "True if PathfinderWalker found a multi-hop escape path. Counts as a positive outcome — the system found a route the flat eligibility check couldn't see.";
sem SessionInsight.navigation_used is "True if NavigationWalker produced a non-empty ActionPlan. The cleanest signal of a successful turn.";
