"""GitHub API helpers for fetching package manifests."""

import from tools.env_util { ensure_dotenv_loaded }

sem parse_github_repo_url = "Parse owner and repo from a github.com URL.";
sem fetch_github_lockfile = "Fetch a repo manifest file (raw GitHub, no 1MB cap).";
sem fetch_github_npm_manifest = "Fetch package-lock.json or fallback to package.json.";

def parse_github_repo_url(repo_url: str) -> dict {
    url = repo_url.strip().rstrip("/");
    if url.endswith(".git") {
        url = url[0:-4];
    }
    marker = "github.com/";
    if marker not in url {
        return {"ok": False, "error": "Not a github.com URL"};
    }
    path = url.split(marker, 1)[1];
    parts = [p for p in path.split("/") if p];
    if len(parts) < 2 {
        return {"ok": False, "error": "Expected https://github.com/owner/repo"};
    }
    return {"ok": True, "owner": parts[0], "repo": parts[1]};
}

def _github_headers(token: str) -> dict {
    headers = {"Accept": "application/vnd.github+json"};
    if token {
        headers["Authorization"] = f"Bearer {token}";
    }
    return headers;
}

def _fetch_via_raw(
    owner: str,
    repo: str,
    branch: str,
    filename: str,
    headers: dict
) -> dict {
    import requests;

    raw_url = (
        f"https://raw.githubusercontent.com/{owner}/{repo}/"
        f"{branch}/{filename}"
    );
    resp = requests.get(raw_url, headers=headers, timeout=120);
    if resp.status_code == 404 {
        return {
            "ok": False,
            "error": f"{filename} not found on branch {branch}",
            "owner": owner,
            "repo": repo
        };
    }
    if resp.status_code != 200 {
        return {
            "ok": False,
            "error": f"raw fetch {resp.status_code}: {resp.text[:200]}",
            "owner": owner,
            "repo": repo
        };
    }
    if not resp.text {
        return {
            "ok": False,
            "error": f"{filename} empty on branch {branch}",
            "owner": owner,
            "repo": repo
        };
    }
    return {
        "ok": True,
        "owner": owner,
        "repo": repo,
        "filename": filename,
        "text": resp.text,
        "branch": branch,
        "source": "raw"
    };
}

def _fetch_via_contents_api(
    owner: str,
    repo: str,
    filename: str,
    headers: dict
) -> dict {
    import base64;
    import requests;

    api_url = (
        f"https://api.github.com/repos/{owner}/{repo}/contents/{filename}"
    );
    resp = requests.get(api_url, headers=headers, timeout=45);
    if resp.status_code == 404 {
        return {
            "ok": False,
            "error": f"{filename} not found on default branch",
            "owner": owner,
            "repo": repo
        };
    }
    if resp.status_code != 200 {
        return {
            "ok": False,
            "error": f"GitHub API {resp.status_code}: {resp.text[:200]}",
            "owner": owner,
            "repo": repo
        };
    }
    payload = resp.json();
    if isinstance(payload, list) {
        return {
            "ok": False,
            "error": f"{filename} is a directory, not a file",
            "owner": owner,
            "repo": repo
        };
    }
    content_b64 = str(payload.get("content", "")).strip();
    text = "";
    if content_b64 {
        text = base64.b64decode(content_b64).decode("utf-8", errors="replace");
    }
    if not text {
        download_url = str(payload.get("download_url", "")).strip();
        if download_url {
            raw_resp = requests.get(download_url, headers=headers, timeout=120);
            if raw_resp.status_code == 200 and raw_resp.text {
                text = raw_resp.text;
            }
        }
    }
    if not text {
        file_size = payload.get("size", 0);
        return {
            "ok": False,
            "error": (
                f"{filename} empty via Contents API (size={file_size})"
            ),
            "owner": owner,
            "repo": repo
        };
    }
    return {
        "ok": True,
        "owner": owner,
        "repo": repo,
        "filename": filename,
        "text": text,
        "source": "contents_api"
    };
}

def fetch_github_lockfile(
    repo_url: str,
    filename: str = "package-lock.json"
) -> dict {
    ensure_dotenv_loaded();
    import os;
    import requests;

    parsed = parse_github_repo_url(repo_url);
    if not parsed["ok"] {
        return parsed;
    }
    owner = str(parsed["owner"]);
    repo = str(parsed["repo"]);
    token = os.environ.get("GITHUB_TOKEN", "");
    headers = _github_headers(token);

    branch = "main";
    repo_api = f"https://api.github.com/repos/{owner}/{repo}";
    repo_resp = requests.get(repo_api, headers=headers, timeout=45);
    if repo_resp.status_code == 200 {
        repo_body = repo_resp.json();
        if isinstance(repo_body, dict) and "default_branch" in repo_body {
            branch = str(repo_body["default_branch"]);
        }
    }

    raw_result = _fetch_via_raw(owner, repo, branch, filename, headers);
    if raw_result["ok"] {
        return raw_result;
    }

    return _fetch_via_contents_api(owner, repo, filename, headers);
}

def fetch_github_npm_manifest(repo_url: str) -> dict {
    lock = fetch_github_lockfile(repo_url, "package-lock.json");
    lock_text = "";
    if "text" in lock {
        lock_text = str(lock["text"]);
    }
    if lock["ok"] and lock_text {
        lock["manifest_kind"] = "lockfile";
        return lock;
    }
    lock_err = str(lock.get("error", ""));
    pkg = fetch_github_lockfile(repo_url, "package.json");
    pkg_text = "";
    if "text" in pkg {
        pkg_text = str(pkg["text"]);
    }
    if pkg["ok"] and pkg_text {
        pkg["manifest_kind"] = "package_json";
        pkg["lockfile_warning"] = lock_err;
        return pkg;
    }
    return {
        "ok": False,
        "error": (
            "Neither package-lock.json nor package.json could be loaded. "
            f"Lockfile: {lock_err}"
        ),
        "owner": lock.get("owner", pkg.get("owner", "")),
        "repo": lock.get("repo", pkg.get("repo", ""))
    };
}

def _github_code_search(
    owner: str,
    repo: str,
    query: str,
    headers: dict
) -> list[str] {
    import requests;

    url = "https://api.github.com/search/code";
    params = {"q": query, "per_page": 10};
    try {
        resp = requests.get(url, headers=headers, params=params, timeout=15);
        if resp.status_code != 200 {
            return [];
        }
        items = resp.json().get("items", []);
        if not isinstance(items, list) {
            return [];
        }
        paths: list[str] = [];
        for item in items {
            if isinstance(item, dict) and item.get("path") {
                paths.append(str(item["path"]));
            }
        }
        return paths;
    } except Exception {
        return [];
    }
}

def search_github_package_imports(
    repo_url: str,
    package_name: str,
    ecosystem: str = "npm"
) -> list[str] {
    ensure_dotenv_loaded();
    import os;

    parsed = parse_github_repo_url(repo_url);
    if not parsed["ok"] {
        return [];
    }
    owner = str(parsed["owner"]);
    repo = str(parsed["repo"]);
    pkg = str(package_name).strip();
    if not pkg {
        return [];
    }
    if pkg.lower() == repo.lower() {
        return [];
    }

    token = os.environ.get("GITHUB_TOKEN", "");
    if not token {
        return [];
    }

    headers = {
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
    };

    eco = str(ecosystem).lower();
    if eco == "auto" {
        eco = "npm";
    }
    scope = f"repo:{owner}/{repo}";
    queries: list[str] = [];

    if eco == "pypi" {
        queries.append(f"import {pkg} {scope}");
        queries.append(f"from {pkg} {scope}");
    } elif eco == "go" {
        queries.append(f'"{pkg}" {scope} extension:go');
    } elif eco == "maven" {
        artifact = pkg;
        if ":" in pkg {
            artifact = pkg.split(":", 1)[1];
        }
        queries.append(f"import {artifact} {scope}");
    } else {
        queries.append(f"import {pkg} {scope}");
        queries.append(f"from {pkg} {scope}");
        queries.append(f'from "{pkg}" {scope}');
        queries.append(f"from '{pkg}' {scope}");
        queries.append(f"require({pkg}) {scope}");
        queries.append(f'require("{pkg}") {scope}');
        queries.append(f"require('{pkg}') {scope}");
        if pkg.startswith("@") {
            queries.append(f'"{pkg}" {scope}');
        }
        if "-" in pkg {
            queries.append(f'"{pkg}" {scope}');
        }
    }

    seen: dict = {};
    merged: list[str] = [];
    for query in queries {
        for path in _github_code_search(owner, repo, query, headers) {
            if path in seen {
                continue;
            }
            seen[path] = True;
            merged.append(path);
            if len(merged) >= 10 {
                return merged;
            }
        }
    }
    if not merged {
        fallback_queries: list[str] = [
            f"{pkg} language:TypeScript {scope}",
            f"{pkg} language:JavaScript {scope}",
        ];
        for query in fallback_queries {
            for path in _github_code_search(owner, repo, query, headers) {
                if path in seen {
                    continue;
                }
                seen[path] = True;
                merged.append(path);
                if len(merged) >= 10 {
                    return merged;
                }
            }
        }
    }
    return merged;
}

"""Deterministic npm manifest parsers (package-lock.json and package.json)."""

import from tools.jac_coerce { as_list }
import from tools.risk_scorer { filter_top_risk_packages }

sem parse_npm_lockfile = "Parse package-lock JSON into packages and dependency edges.";
sem parse_npm_package_json = "Parse package.json direct dependencies into a shallow graph.";

def _normalize_version_spec(spec: str) -> str {
    s = str(spec).strip();
    if not s or s == "*" {
        return "";
    }
    if s.startswith("^") {
        s = s[1:].strip();
    } elif s.startswith("~") {
        s = s[1:].strip();
    } elif s.startswith(">=") {
        s = s[2:].strip();
    } elif s.startswith("<=") {
        s = s[2:].strip();
    } elif s.startswith(">") {
        s = s[1:].strip();
    } elif s.startswith("<") {
        s = s[1:].strip();
    } elif s.startswith("=") {
        s = s[1:].strip();
    }
    if "||" in s {
        s = s.split("||", 1)[0].strip();
    }
    if " - " in s {
        parts = s.split(" - ");
        s = parts[-1].strip();
    }
    return s;
}

def parse_npm_package_json(manifest_text: str) -> dict {
    import json;

    try {
        data = json.loads(manifest_text);
    } except Exception as e {
        return {"ok": False, "error": f"Invalid JSON: {e}"};
    }
    if not isinstance(data, dict) {
        return {"ok": False, "error": "package.json root must be an object"};
    }

    root_name = str(data.get("name", "root"));
    root_version = _normalize_version_spec(str(data.get("version", "0.0.0")));
    if not root_version {
        root_version = "0.0.0";
    }
    root_key = f"{root_name}@{root_version}";

    packages: list[dict] = [
        {
            "key": root_key,
            "name": root_name,
            "version": root_version,
            "is_direct": True,
            "depth": 0,
            "lock_path": ""
        }
    ];
    edges: list[dict] = [];
    deps = data.get("dependencies", {});
    if not isinstance(deps, dict) {
        deps = {};
    }

    dep_keys = list(deps.keys());
    for dep_name in dep_keys {
        dep_spec = str(deps[dep_name]);
        dep_version = _normalize_version_spec(dep_spec);
        if not dep_version {
            dep_version = dep_spec;
        }
        dep_key = f"{dep_name}@{dep_version}";
        packages.append(
            {
                "key": dep_key,
                "name": str(dep_name),
                "version": dep_version,
                "is_direct": True,
                "depth": 1,
                "lock_path": f"node_modules/{dep_name}"
            }
        );
        edges.append(
            {
                "from_key": root_key,
                "to_key": dep_key,
                "required_version": dep_spec
            }
        );
    }

    if len(packages) <= 1 {
        return {
            "ok": False,
            "error": "package.json has no dependencies field entries"
        };
    }

    return {
        "ok": True,
        "packages": packages,
        "edges": edges,
        "package_count": len(packages),
        "manifest_kind": "package_json"
    };
}

def _lock_path_name(lock_path: str) -> str {
    if lock_path == "" {
        return "";
    }
    if lock_path.startswith("node_modules/") {
        return lock_path.split("node_modules/")[-1];
    }
    return lock_path;
}

def parse_npm_lockfile(
    lock_text: str,
    max_packages: int = 200
) -> dict {
    import json;

    try {
        data = json.loads(lock_text);
    } except Exception as e {
        return {"ok": False, "error": f"Invalid JSON: {e}"};
    }
    raw_packages = data.get("packages", {});
    if not raw_packages {
        return {
            "ok": False,
            "error": "No packages field — need package-lock.json v2/v3"
        };
    }

    packages: list[dict] = [];
    edges: list[dict] = [];
    index: dict = {};
    name_to_key: dict = {};

    lock_paths = list(raw_packages.keys());
    for lock_path in lock_paths {
        lock_path_str: str = str(lock_path);
        meta = raw_packages[lock_path];
        if not isinstance(meta, dict) {
            continue;
        }
        version = meta.get("version", "");
        if not version {
            continue;
        }
        name = meta.get("name", _lock_path_name(lock_path_str));
        if not name {
            continue;
        }
        key = f"{name}@{version}";
        is_direct = False;
        if lock_path_str == "" {
            is_direct = True;
        } elif lock_path_str.startswith("node_modules/") {
            rest: str = str(lock_path_str.removeprefix("node_modules/"));
            is_direct = "/" not in rest;
        }
        depth = 0;
        if lock_path_str != "" {
            depth = lock_path_str.count("node_modules/");
        }
        if key not in index {
            index[key] = len(packages);
            name_to_key[str(name)] = key;
            packages.append(
                {
                    "key": key,
                    "name": name,
                    "version": version,
                    "is_direct": is_direct,
                    "depth": depth,
                    "lock_path": lock_path_str
                }
            );
        }
    }

    for lock_path in lock_paths {
        lock_path_str: str = str(lock_path);
        meta = raw_packages[lock_path];
        if not isinstance(meta, dict) {
            continue;
        }
        from_version = meta.get("version", "");
        if not from_version {
            continue;
        }
        from_name = meta.get("name", _lock_path_name(lock_path_str));
        if not from_name {
            continue;
        }
        from_key = f"{from_name}@{from_version}";
        if from_key not in index {
            continue;
        }
        deps = meta.get("dependencies", {});
        if not isinstance(deps, dict) {
            continue;
        }
        dep_keys = list(deps.keys());
        for dep_name in dep_keys {
            dep_spec = deps[dep_name];
            dep_str = str(dep_name);
            to_key = "";
            if dep_str in name_to_key {
                to_key = name_to_key[dep_str];
            }
            if not to_key {
                continue;
            }
            edges.append(
                {
                    "from_key": from_key,
                    "to_key": to_key,
                    "required_version": str(dep_spec)
                }
            );
        }
    }

    filtered = filter_top_risk_packages(packages, edges, max_packages);
    final_packages = as_list(filtered["packages"]);
    final_edges = as_list(filtered["edges"]);

    return {
        "ok": True,
        "packages": final_packages,
        "edges": final_edges,
        "package_count": len(final_packages),
        "truncated": filtered["truncated"],
        "original_package_count": filtered["original_package_count"],
        "filter_method": filtered["method"]
    };
}

"""NVD CVE lookup (deterministic REST, no LLM)."""

import from tools.env_util { ensure_dotenv_loaded }

sem nvd_search_cve = "Search NVD for CVEs related to a package name; returns normalized dicts.";

glob nvd_cache: dict[str, list[dict]] = {};

def _severity_from_score(score: float) -> str {
    if score >= 9.0 {
        return "CRITICAL";
    }
    if score >= 7.0 {
        return "HIGH";
    }
    if score >= 4.0 {
        return "MEDIUM";
    }
    if score > 0.0 {
        return "LOW";
    }
    return "UNKNOWN";
}

def _cve_text_matches_package(text: str, package_name: str) -> bool {
    if not text {
        return False;
    }
    lower_text = text.lower();
    pkg = package_name.lower();
    if pkg in lower_text {
        return True;
    }
    npm_needle = f"npm:{pkg}";
    if npm_needle in lower_text {
        return True;
    }
    return False;
}

def nvd_search_cve(
    package_name: str,
    version: str = "",
    ecosystem: str = "npm"
) -> list[dict] {
    cache_key = f"{ecosystem}:{package_name.lower()}@{version}";
    if cache_key in nvd_cache {
        return nvd_cache[cache_key];
    }

    ensure_dotenv_loaded();
    import os;
    import requests;

    api_key = os.environ.get("NVD_API_KEY", "");
    headers = {};
    if api_key {
        headers["apiKey"] = api_key;
    }
    eco = str(ecosystem).lower();
    if eco == "pypi" {
        query = f"python {package_name}";
    } elif eco == "go" {
        query = f"go {package_name}";
    } elif eco == "maven" {
        query = f"maven {package_name}";
    } else {
        query = f"npm {package_name}";
    }
    url = "https://services.nvd.nist.gov/rest/json/cves/2.0";
    params = {"keywordSearch": query, "resultsPerPage": 20};
    resp = requests.get(url, params=params, headers=headers, timeout=45);
    if resp.status_code != 200 {
        return [];
    }
    body = resp.json();
    vulns = body.get("vulnerabilities", []);
    results: list[dict] = [];
    for item in vulns {
        cve = item.get("cve", {});
        cve_id = cve.get("id", "");
        if not cve_id {
            continue;
        }
        score = 0.0;
        metrics = cve.get("metrics", {});
        for metric_key in ["cvssMetricV31", "cvssMetricV30", "cvssMetricV2"] {
            metric_list = metrics.get(metric_key, []);
            if metric_list {
                cvss_data = metric_list[0].get("cvssData", {});
                score = float(str(cvss_data.get("baseScore", 0.0)));
                break;
            }
        }
        descriptions = cve.get("descriptions", []);
        desc = "";
        for d in descriptions {
            if d.get("lang") == "en" {
                desc = d.get("value", "");
                break;
            }
        }
        if not _cve_text_matches_package(desc, package_name) {
            continue;
        }
        results.append(
            {
                "cve_id": cve_id,
                "cvss_score": score,
                "severity": _severity_from_score(score),
                "description": desc[:500],
                "fixed_version": "",
                "source": "nvd"
            }
        );
    }
    nvd_cache[cache_key] = results;
    return results;
}

"""OSV.dev vulnerability lookup (accurate per ecosystem + version)."""

import from tools.ecosystem_util { osv_ecosystem_for }
import from tools.env_util { ensure_dotenv_loaded }
import from tools.jac_coerce { as_list }

sem osv_query_npm = "Query OSV for npm package@version; returns normalized CVE dicts.";
sem osv_query_ecosystem = "Query OSV for any supported DepGraph ecosystem.";

glob osv_cache: dict[str, list[dict]] = {};

def _severity_from_score(score: float) -> str {
    if score >= 9.0 {
        return "CRITICAL";
    }
    if score >= 7.0 {
        return "HIGH";
    }
    if score >= 4.0 {
        return "MEDIUM";
    }
    if score > 0.0 {
        return "LOW";
    }
    return "UNKNOWN";
}

def _score_from_severity_label(label: str) -> float {
    u = str(label).strip().upper();
    if u == "CRITICAL" {
        return 9.8;
    }
    if u == "HIGH" {
        return 8.1;
    }
    if u == "MODERATE" {
        return 5.5;
    }
    if u == "MEDIUM" {
        return 5.5;
    }
    if u == "LOW" {
        return 3.1;
    }
    return 0.0;
}

def _extract_fixed_version(item: dict) -> str {
    affected_list = as_list(item.get("affected", []));
    for affected in affected_list {
        if not isinstance(affected, dict) {
            continue;
        }
        ranges = as_list(affected.get("ranges", []));
        for range_ in ranges {
            if not isinstance(range_, dict) {
                continue;
            }
            events = as_list(range_.get("events", []));
            for event in events {
                if not isinstance(event, dict) {
                    continue;
                }
                if "fixed" in event {
                    fixed = str(event["fixed"]);
                    if fixed and fixed != "0" {
                        return fixed;
                    }
                }
            }
        }
    }
    return "";
}

def _osv_query_raw(
    package_name: str,
    version: str,
    osv_ecosystem: str
) -> list[dict] {
    cache_key = f"{osv_ecosystem}:{package_name.lower()}@{version}";
    if cache_key in osv_cache {
        return osv_cache[cache_key];
    }

    ensure_dotenv_loaded();
    import requests;

    url = "https://api.osv.dev/v1/query";
    payload = {
        "package": {"name": package_name, "ecosystem": osv_ecosystem},
        "version": version
    };
    resp = requests.post(url, json=payload, timeout=30);
    if resp.status_code != 200 {
        osv_cache[cache_key] = [];
        return [];
    }
    body = resp.json();
    vulns = as_list(body.get("vulns", []));
    results: list[dict] = [];
    for item in vulns {
        if not isinstance(item, dict) {
            continue;
        }
        cve_id = str(item.get("id", ""));
        aliases = as_list(item.get("aliases", []));
        for alias in aliases {
            alias_str = str(alias);
            if alias_str.startswith("CVE-") {
                cve_id = alias_str;
                break;
            }
        }
        if not cve_id {
            continue;
        }
        score = 0.0;
        db = item.get("database_specific", {});
        if isinstance(db, dict) {
            if "cvss_score" in db {
                try {
                    score = float(str(db["cvss_score"]));
                } except Exception {}
            }
            if score <= 0.0 and "severity" in db {
                label_score = _score_from_severity_label(str(db["severity"]));
                if label_score > score {
                    score = label_score;
                }
            }
        }
        severities = as_list(item.get("severity", []));
        for sev in severities {
            if not isinstance(sev, dict) {
                continue;
            }
            if "score" not in sev {
                continue;
            }
            raw = str(sev["score"]).strip();
            if not raw {
                continue;
            }
            cvss_prefix = "CVSS";
            if raw.startswith(cvss_prefix) {
                continue;
            }
            try {
                candidate = float(raw);
                if candidate > score {
                    score = candidate;
                }
            } except Exception {}
        }
        if score <= 0.0 {
            ecosystem_specific = item.get("ecosystem_specific", {});
            if isinstance(ecosystem_specific, dict) {
                sev_label = str(ecosystem_specific.get("severity", ""));
                if sev_label {
                    label_score = _score_from_severity_label(sev_label);
                    if label_score > 0.0 {
                        score = label_score;
                    }
                }
            }
        }
        summary = str(item.get("summary", ""));
        if not summary {
            details = str(item.get("details", ""));
            summary = details[0:500];
        }
        results.append(
            {
                "cve_id": cve_id,
                "cvss_score": score,
                "severity": _severity_from_score(score),
                "description": summary[0:500],
                "fixed_version": _extract_fixed_version(item),
                "source": "osv"
            }
        );
    }
    osv_cache[cache_key] = results;
    return results;
}

def osv_query_npm(package_name: str, version: str) -> list[dict] {
    return _osv_query_raw(package_name, version, "npm");
}

def osv_query_ecosystem(
    package_name: str,
    version: str,
    depgraph_ecosystem: str
) -> list[dict] {
    osv_eco = osv_ecosystem_for(depgraph_ecosystem);
    return _osv_query_raw(package_name, version, osv_eco);
}

"""In-memory risk scoring for dependency prioritization (no API calls)."""

import from tools.jac_coerce { as_list }

glob HIGH_RISK_KEYWORDS: list[str] = [
    "jwt", "auth", "crypto", "passport", "bcrypt", "serialize",
    "eval", "exec", "shell", "xml", "yaml", "parse", "request",
    "axios", "express", "lodash", "moment", "vm2", "node-serialize",
    "log4", "token", "cookie", "session", "oauth", "ssl", "tls",
    "https", "http", "fetch", "got", "request", "body-parser"
];

def _name_has_high_risk_keyword(name: str) -> bool {
    name_lower = name.lower();
    for kw in HIGH_RISK_KEYWORDS {
        if kw in name_lower {
            return True;
        }
    }
    return False;
}

def _major_version_bonus(version: str) -> int {
    ver = str(version).strip();
    if not ver {
        return 0;
    }
    parts = ver.split(".");
    if not parts {
        return 0;
    }
    major_str = parts[0];
    try {
        major = int(major_str);
    } except Exception {
        return 0;
    }
    if major == 0 {
        return 40;
    }
    if major == 1 {
        return 20;
    }
    if major == 2 {
        return 10;
    }
    return 0;
}

def package_risk_score(
    name: str,
    version: str,
    depth: int,
    is_direct: bool
) -> int {
    score = 0;
    if depth == 0 {
        score += 100;
    } elif depth == 1 {
        score += 80;
    } else {
        depth_bonus = 10 - depth;
        if depth_bonus > 0 {
            score += depth_bonus * 10;
        }
    }
    if _name_has_high_risk_keyword(name) {
        score += 50;
    }
    score += _major_version_bonus(version);
    if is_direct {
        score += 15;
    }
    return score;
}

def filter_top_risk_packages(
    packages: list[dict],
    edges: list[dict],
    max_packages: int = 200
) -> dict {
    pkg_count = len(packages);
    if pkg_count <= max_packages {
        return {
            "packages": packages,
            "edges": edges,
            "truncated": False,
            "original_package_count": pkg_count,
            "method": "none"
        };
    }
    key_to_score: dict = {};
    for pkg in packages {
        pkg_key = str(pkg["key"]);
        pkg_depth = 0;
        if "depth" in pkg {
            pkg_depth = int(pkg["depth"]);
        }
        pkg_direct = False;
        if "is_direct" in pkg {
            pkg_direct = bool(pkg["is_direct"]);
        }
        key_to_score[pkg_key] = package_risk_score(
            str(pkg["name"]),
            str(pkg["version"]),
            pkg_depth,
            pkg_direct
        );
    }
    selected: list[dict] = [];
    selected_keys: dict = {};
    picks = 0;
    while picks < max_packages {
        best_key = "";
        best_score = -1;
        for pkg_key in key_to_score {
            if pkg_key in selected_keys {
                continue;
            }
            entry_score = key_to_score[pkg_key];
            if entry_score > best_score {
                best_score = entry_score;
                best_key = pkg_key;
            }
        }
        if not best_key {
            break;
        }
        for pkg in packages {
            if str(pkg["key"]) == best_key {
                selected.append(pkg);
                break;
            }
        }
        selected_keys[best_key] = True;
        picks += 1;
    }
    kept_edges: list[dict] = [];
    for edge in edges {
        from_key = str(edge["from_key"]);
        to_key = str(edge["to_key"]);
        if from_key in selected_keys and to_key in selected_keys {
            kept_edges.append(edge);
        }
    }
    return {
        "packages": selected,
        "edges": kept_edges,
        "truncated": True,
        "original_package_count": pkg_count,
        "method": "risk_score"
    };
}

"""Spawned when a critical CVE is found — transitive OSV follow-up."""

import from graph.nodes { Package, CVE }
import from tools.cve_lookup { lookup_package_cves }

walker DeepDiveWalker {
    has target_name: str;
    has target_version: str;
    has cve_id: str;
    has cvss_score: float = 0.0;
    has ecosystem: str = "npm";
    has max_visits: int = 10;
    has max_depth: int = 3;
    has visit_count: int = 0;
    has findings: list[dict] = [];
    has transitive_findings: list[dict] = [];
    has reported_start: bool = False;

    can analyze with Package entry {
        if here.depth > self.max_depth {
            disengage;
        }
        if self.visit_count >= self.max_visits {
            report {
                "event": "deep_dive_complete",
                "root_package": self.target_name,
                "root_version": self.target_version,
                "cve_id": self.cve_id,
                "packages_checked": self.visit_count,
                "findings": self.findings
            };
            disengage;
        }
        self.visit_count += 1;

        if not self.reported_start {
            self.reported_start = True;
            report {
                "event": "deep_dive",
                "package": self.target_name,
                "version": self.target_version,
                "cve_id": self.cve_id,
                "cvss_score": self.cvss_score,
                "depth": here.depth,
                "message": "Investigating transitive deps of critical finding"
            };
        }

        if here.name != self.target_name {
            cves = lookup_package_cves(here.name, here.version, self.ecosystem);
            max_cvss = 0.0;
            top_cve = "";
            for cve_data in cves {
                cve_node = CVE(
                    cve_id=cve_data["cve_id"],
                    cvss_score=cve_data["cvss_score"],
                    severity=cve_data["severity"],
                    description=cve_data["description"],
                    fixed_version=cve_data["fixed_version"]
                );
                here ++> cve_node;
                if cve_data["cvss_score"] > max_cvss {
                    max_cvss = cve_data["cvss_score"];
                    top_cve = str(cve_data["cve_id"]);
                }
            }
            if cves {
                self.findings.append(
                    {
                        "package": here.name,
                        "version": here.version,
                        "cve_count": len(cves),
                        "max_cvss": max_cvss,
                        "top_cve": top_cve,
                        "depth": here.depth
                    }
                );
                self.transitive_findings.append(
                    {
                        "package": here.name,
                        "version": here.version,
                        "cvss": max_cvss,
                        "cve_id": top_cve
                    }
                );
                report {
                    "event": "deep_dive_finding",
                    "package": here.name,
                    "version": here.version,
                    "cve_count": len(cves),
                    "max_cvss": max_cvss,
                    "top_cve": top_cve,
                    "depth": here.depth
                };
            }
        }

        visit [here ->:DependsOn:->][?:Package];
    }
}

"""Main orchestrator — manifest ingest, graph build, spawn subtree walkers."""

import from graph.nodes { InvestigationSession, Package, CVE }
import from graph.builder { build_package_graph }
import from graph.snapshot_util {
    build_graph_snapshot,
    pkg_node_id,
    severity_from_cvss
}
import from tools.jac_coerce { as_list }
import from tools.manifest_resolver {
    fetch_ecosystem_manifest,
    parse_ecosystem_manifest
}
import from tools.risk_scorer { package_risk_score }
import from walkers.remediation_walker { RemediationWalker }
import from walkers.report_util { generate_executive_summary_safe }
import from walkers.route_util { select_spawn_root_index }
import from walkers.subtree_walker { SubtreeWalker }
import from walkers.usage_context_util {
    package_usage_surface,
    compute_exploitability,
    package_has_usage_context,
    attach_usage_context_for_package,
    refresh_findings_usage,
    is_workspace_package,
}
import from tools.investigation_runner { session_push }

def _spawn_roots_fallback(candidates: list[Package], pick_count: int) -> list[Package] {
    if len(candidates) <= pick_count {
        return candidates;
    }
    selected: list[Package] = [];
    selected_names: dict = {};
    picks = 0;
    while picks < pick_count {
        best_idx = -1;
        best_score = -1;
        idx = 0;
        for pkg_node in candidates {
            if pkg_node.name in selected_names {
                idx += 1;
                continue;
            }
            score = package_risk_score(
                pkg_node.name,
                pkg_node.version,
                pkg_node.depth,
                pkg_node.is_direct
            );
            if score > best_score {
                best_score = score;
                best_idx = idx;
            }
            idx += 1;
        }
        if best_idx < 0 {
            break;
        }
        chosen = candidates[best_idx];
        selected.append(chosen);
        selected_names[chosen.name] = True;
        picks += 1;
    }
    return selected;
}

def _top_risk_candidates(
    candidates: list[Package],
    limit: int
) -> list[Package] {
    if len(candidates) <= limit {
        return candidates;
    }
    return _spawn_roots_fallback(candidates, limit);
}

walker:pub DepGraphAgent {
    has repo_url: str;
    has ecosystem: str = "npm";
    has max_direct_deps: int = 8;
    has max_graph_packages: int = 300;
    has max_spawn_llm_pool: int = 30;
    has session_id: str = "";
    has reports: list[dict] = [];

    can start with Root entry {
        manifest_result = fetch_ecosystem_manifest(
            self.repo_url,
            self.ecosystem
        );
        if not manifest_result["ok"] {
            err_msg = str(manifest_result.get("error", "manifest fetch failed"));
            report {"event": "error", "message": err_msg};
            if self.session_id {
                session_push(
                    self.session_id,
                    {"event": "error", "message": err_msg}
                );
            }
            disengage;
        }

        active_ecosystem = self.ecosystem;
        if "ecosystem" in manifest_result {
            active_ecosystem = str(manifest_result["ecosystem"]);
        }
        if active_ecosystem == "auto" {
            active_ecosystem = "npm";
        }

        session = InvestigationSession(
            repo_url=self.repo_url,
            ecosystem=active_ecosystem,
            status="running"
        );
        root ++> session;
        report {
            "event": "session_started",
            "repo_url": self.repo_url,
            "ecosystem": active_ecosystem,
            "session_id": self.session_id
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "session_started",
                    "repo_url": self.repo_url,
                    "ecosystem": active_ecosystem,
                    "session_id": self.session_id
                }
            );
        }

        manifest_kind = str(manifest_result.get("manifest_kind", "lockfile"));
        report {
            "event": "lockfile_fetched",
            "owner": manifest_result["owner"],
            "repo": manifest_result["repo"],
            "filename": manifest_result["filename"],
            "manifest_kind": manifest_kind,
            "ecosystem": active_ecosystem
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "lockfile_fetched",
                    "owner": manifest_result["owner"],
                    "repo": manifest_result["repo"],
                    "filename": manifest_result["filename"],
                    "manifest_kind": manifest_kind,
                    "ecosystem": active_ecosystem
                }
            );
        }

        manifest_text: str = str(manifest_result["text"]);
        report {
            "event": "manifest_parsing",
            "filename": manifest_result["filename"],
            "bytes": len(manifest_text),
            "ecosystem": active_ecosystem
        };
        parsed = parse_ecosystem_manifest(
            manifest_text,
            active_ecosystem,
            manifest_kind,
            self.max_graph_packages
        );
        if not parsed["ok"] {
            report {"event": "error", "message": parsed["error"]};
            disengage;
        }
        truncated = False;
        if "truncated" in parsed {
            truncated = parsed["truncated"];
        }
        filter_method = "none";
        if "filter_method" in parsed {
            filter_method = str(parsed["filter_method"]);
        }
        original_cnt = parsed["package_count"];
        if "original_package_count" in parsed {
            original_cnt = parsed["original_package_count"];
        }
        report {
            "event": "manifest_parsed",
            "package_count": parsed["package_count"],
            "truncated": truncated,
            "original_package_count": original_cnt,
            "filter_method": filter_method
        };

        pkg_count = build_package_graph(session, parsed);
        edge_list = as_list(parsed.get("edges", []));
        edge_cnt = 0;
        for _x in edge_list {
            edge_cnt += 1;
        }
        report {
            "event": "graph_built",
            "package_count": pkg_count,
            "edge_count": edge_cnt,
            "truncated": truncated,
            "filter_method": filter_method
        };

        session_packages: list[Package] = [];
        for pkg_node in [session-->][?:Package] {
            session_packages.append(pkg_node);
        }
        snapshot = build_graph_snapshot(session_packages, parsed, []);
        report {
            "event": "graph_snapshot",
            "nodes": snapshot["nodes"],
            "edges": snapshot["edges"],
            "package_count": pkg_count,
            "edge_count": edge_cnt
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "graph_snapshot",
                    "nodes": snapshot["nodes"],
                    "edges": snapshot["edges"],
                    "package_count": pkg_count,
                    "edge_count": edge_cnt
                }
            );
        }

        candidates: list[Package] = [];
        for pkg_node in [session-->][?:Package] {
            if is_workspace_package(pkg_node, self.repo_url) {
                continue;
            }
            if pkg_node.is_direct and pkg_node.depth <= 1 {
                candidates.append(pkg_node);
            }
        }
        if not candidates {
            for pkg_node in [session-->][?:Package] {
                if pkg_node.depth == 0 {
                    continue;
                }
                candidates.append(pkg_node);
            }
        }

        spawn_pool = _top_risk_candidates(
            candidates,
            self.max_spawn_llm_pool
        );

        spawn_targets: list[Package] = [];
        spawn_mode = "fallback";
        llm_spawn_picks = 0;
        spawn_llm_failures = 0;
        remaining_pool: list[Package] = [];
        for pkg_node in spawn_pool {
            remaining_pool.append(pkg_node);
        }

        report {
            "event": "spawn_decision",
            "candidate_count": len(candidates),
            "llm_pool_count": len(spawn_pool),
            "pick_count": self.max_direct_deps,
            "message": "LLM selecting subtree spawn roots from top risk pool"
        };

        while (
            len(spawn_targets) < self.max_direct_deps
            and len(remaining_pool) > 0
        ) {
            descriptions = "";
            slot = 0;
            for pkg_node in remaining_pool {
                descriptions = (
                    f"{descriptions}{slot}) {pkg_node.name}\n"
                );
                slot += 1;
            }

            picked_idx = -1;
            spawn_err = "";
            attempts = 0;
            while attempts < 2 and picked_idx < 0 {
                attempts += 1;
                try {
                    raw_spawn = select_spawn_root_index(descriptions);
                    if raw_spawn and len(raw_spawn) >= 1 {
                        pick = raw_spawn[0];
                        if pick >= 0 and pick < len(remaining_pool) {
                            picked_idx = pick;
                        }
                    }
                } except Exception as e {
                    spawn_err = str(e);
                }
            }
            if picked_idx < 0 {
                spawn_llm_failures += 1;
                risk_one = _spawn_roots_fallback(remaining_pool, 1);
                if not risk_one {
                    break;
                }
                chosen = risk_one[0];
            } else {
                chosen = remaining_pool[picked_idx];
                llm_spawn_picks += 1;
            }
            spawn_targets.append(chosen);
            next_pool: list[Package] = [];
            for pkg_node in remaining_pool {
                if pkg_node.name != chosen.name {
                    next_pool.append(pkg_node);
                }
            }
            remaining_pool = next_pool;
        }

        if llm_spawn_picks > 0 {
            spawn_mode = "llm";
        }
        if spawn_llm_failures > 0 and llm_spawn_picks == 0 {
            report {
                "event": "spawn_llm_failed",
                "reason": "All spawn LLM picks failed",
                "failures": spawn_llm_failures
            };
        } elif spawn_llm_failures > 0 {
            report {
                "event": "spawn_llm_partial",
                "llm_picks": llm_spawn_picks,
                "risk_picks": spawn_llm_failures,
                "message": "Some spawn picks used risk fallback after LLM empty response"
            };
        }
        if len(spawn_targets) < self.max_direct_deps {
            picked_names: dict = {};
            for pkg_node in spawn_targets {
                picked_names[pkg_node.name] = True;
            }
            extra_pool: list[Package] = [];
            for pkg_node in candidates {
                if pkg_node.name not in picked_names {
                    extra_pool.append(pkg_node);
                }
            }
            need = self.max_direct_deps - len(spawn_targets);
            extras = _spawn_roots_fallback(extra_pool, need);
            for pkg_node in extras {
                spawn_targets.append(pkg_node);
            }
            if llm_spawn_picks == 0 {
                spawn_mode = "fallback";
            }
        }

        spawned_names = "";
        for pkg_node in spawn_targets {
            spawned_names = f"{spawned_names}{pkg_node.name} ";
        }
        spawn_root_ids: list[str] = [];
        for pkg_node in spawn_targets {
            spawn_root_ids.append(pkg_node_id(pkg_node.name, pkg_node.version));
        }
        snapshot_after = build_graph_snapshot(
            session_packages,
            parsed,
            spawn_root_ids
        );
        report {
            "event": "spawn_roots",
            "roots": spawn_root_ids
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "spawn_roots",
                    "roots": spawn_root_ids
                }
            );
        }
        report {
            "event": "graph_snapshot",
            "nodes": snapshot_after["nodes"],
            "edges": snapshot_after["edges"],
            "package_count": pkg_count,
            "edge_count": edge_cnt
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "graph_snapshot",
                    "nodes": snapshot_after["nodes"],
                    "edges": snapshot_after["edges"],
                    "package_count": pkg_count,
                    "edge_count": edge_cnt
                }
            );
        }

        report {
            "event": "spawn_chosen",
            "mode": spawn_mode,
            "targets": spawned_names.strip(),
            "count": len(spawn_targets),
            "llm_picks": llm_spawn_picks,
            "risk_picks": spawn_llm_failures
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "spawn_chosen",
                    "mode": spawn_mode,
                    "targets": spawned_names.strip(),
                    "count": len(spawn_targets),
                    "llm_picks": llm_spawn_picks,
                    "risk_picks": spawn_llm_failures
                }
            );
        }

        for pkg_node in spawn_targets {
            attach_usage_context_for_package(
                self.repo_url,
                pkg_node,
                self.session_id,
                session_packages
            );
        }

        spawned = 0;
        lookup_count = 0;
        route_llm_count = 0;
        route_fallback_count = 0;
        deep_dive_names: dict = {};
        for pkg_node in spawn_targets {
            subtree = SubtreeWalker(
                depth_limit=3,
                max_visits=5,
                session_id=self.session_id,
                repo_url=self.repo_url,
                session_packages=session_packages,
                ecosystem=active_ecosystem
            ) spawn pkg_node;
            sub_lookups = subtree.osv_lookup_count;
            for entry in subtree.reports {
                report entry;
                if "event" in entry {
                    ev_name = str(entry["event"]);
                    if ev_name == "route_chosen" {
                        rmode = str(entry.get("mode", "fallback"));
                        if rmode == "llm" {
                            route_llm_count += 1;
                        } else {
                            route_fallback_count += 1;
                        }
                    }
                    if ev_name == "deep_dive" {
                        dp = str(entry.get("package", ""));
                        if dp {
                            deep_dive_names[dp] = True;
                        }
                    }
                }
                if sub_lookups == 0 and "event" in entry {
                    if entry["event"] == "nvd_lookup" {
                        sub_lookups += 1;
                    }
                }
            }
            lookup_count += sub_lookups;
            spawned += 1;
        }

        for pkg_node in session_packages {
            cve_nodes = [pkg_node-->][?:CVE];
            if not cve_nodes {
                continue;
            }
            if package_has_usage_context(pkg_node) {
                continue;
            }
            attach_usage_context_for_package(
                self.repo_url,
                pkg_node,
                self.session_id,
                session_packages
            );
        }

        for pkg_node in session_packages {
            cve_nodes = [pkg_node-->][?:CVE];
            if not cve_nodes {
                continue;
            }
            if package_usage_surface(pkg_node) != "unknown" {
                continue;
            }
            attach_usage_context_for_package(
                self.repo_url,
                pkg_node,
                self.session_id,
                session_packages
            );
        }

        report {
            "event": "subtrees_spawned",
            "spawn_count": spawned,
            "max_direct_deps": self.max_direct_deps,
            "spawn_mode": spawn_mode
        };

        findings: list[dict] = [];
        for pkg_node in [session-->][?:Package] {
            cve_nodes = [pkg_node-->][?:CVE];
            if not cve_nodes {
                continue;
            }
            max_cvss = 0.0;
            top_cve = "";
            fixed_version = "";
            for cve_node in cve_nodes {
                if cve_node.cvss_score > max_cvss {
                    max_cvss = cve_node.cvss_score;
                    top_cve = cve_node.cve_id;
                }
                if cve_node.fixed_version and not fixed_version {
                    fixed_version = str(cve_node.fixed_version);
                }
            }
            finding_surface = package_usage_surface(pkg_node);
            findings.append(
                {
                    "package": pkg_node.name,
                    "version": pkg_node.version,
                    "cve_count": len(cve_nodes),
                    "max_cvss": max_cvss,
                    "top_cve": top_cve,
                    "severity": severity_from_cvss(max_cvss),
                    "depth": pkg_node.depth,
                    "is_direct": pkg_node.is_direct,
                    "deep_dive_triggered": pkg_node.name in deep_dive_names,
                    "fixed_version": fixed_version,
                    "usage_surface": finding_surface,
                    "exploitability": compute_exploitability(
                        max_cvss,
                        finding_surface
                    )
                }
            );
        }

        for item in findings {
            pkg_name = str(item["package"]);
            for pkg_node in session_packages {
                if pkg_node.name != pkg_name {
                    continue;
                }
                if str(pkg_node.version) != str(item["version"]) {
                    continue;
                }
                if not package_has_usage_context(pkg_node) {
                    attach_usage_context_for_package(
                        self.repo_url,
                        pkg_node,
                        self.session_id,
                        session_packages
                    );
                }
                break;
            }
        }
        refresh_findings_usage(findings, session_packages);

        for pkg_node in [session-->][?:Package] {
            cve_nodes = [pkg_node-->][?:CVE];
            if not cve_nodes {
                continue;
            }
            remed = RemediationWalker() spawn pkg_node;
            for entry in remed.reports {
                report entry;
            }
        }

        findings_lines = "";
        for item in findings {
            findings_lines = (
                f"{findings_lines}{item['package']}@{item['version']} "
                f"cvss={item['max_cvss']} exploitability={item['exploitability']} "
                f"surface={item['usage_surface']} ({item['top_cve']})\n"
            );
        }
        if not findings_lines {
            findings_lines = "No vulnerable packages in scanned subtrees.";
        }
        critical_count = 0;
        for item in findings {
            if item["max_cvss"] >= 9.0 {
                critical_count += 1;
            }
        }

        report {"event": "report_generating"};
        summary = "";
        try {
            summary = generate_executive_summary_safe(
                self.repo_url,
                findings_lines,
                lookup_count,
                len(findings)
            );
        } except Exception {
            summary = (
                f"Scanned {lookup_count} packages across {spawned} subtrees. "
                f"Found {len(findings)} vulnerable package(s)."
            );
        }
        report {
            "event": "report_generated",
            "summary": summary
        };

        report {
            "event": "investigation_complete",
            "packages_scanned": lookup_count,
            "packages_in_graph": pkg_count,
            "subtrees_spawned": spawned,
            "vulnerable_count": len(findings),
            "critical_count": critical_count,
            "spawn_mode": spawn_mode,
            "route_llm_count": route_llm_count,
            "route_fallback_count": route_fallback_count,
            "truncated": truncated,
            "original_package_count": original_cnt,
            "findings": findings,
            "executive_summary": summary
        };
        if self.session_id {
            session_push(
                self.session_id,
                {
                    "event": "investigation_complete",
                    "packages_scanned": lookup_count,
                    "packages_in_graph": pkg_count,
                    "subtrees_spawned": spawned,
                    "vulnerable_count": len(findings),
                    "critical_count": critical_count,
                    "spawn_mode": spawn_mode,
                    "route_llm_count": route_llm_count,
                    "route_fallback_count": route_fallback_count,
                    "truncated": truncated,
                    "original_package_count": original_cnt,
                    "findings": findings,
                    "executive_summary": summary
                }
            );
        }
    }
}

"""Classify package usage from GitHub import file paths (deterministic, no LLM)."""

def _path_matches_ecosystem(path_lower: str, ecosystem: str) -> bool {
    eco = str(ecosystem).lower();
    if eco == "pypi" {
        return (
            path_lower.endswith(".py")
            or path_lower.endswith(".pyi")
        );
    }
    if eco == "go" {
        return path_lower.endswith(".go");
    }
    if eco == "maven" {
        return (
            path_lower.endswith(".java")
            or path_lower.endswith(".kt")
            or path_lower.endswith(".kts")
            or path_lower.endswith(".scala")
            or path_lower.endswith(".groovy")
        );
    }
    if eco == "auto" {
        return (
            path_lower.endswith(".ts")
            or path_lower.endswith(".js")
            or path_lower.endswith(".tsx")
            or path_lower.endswith(".jsx")
            or path_lower.endswith(".mjs")
            or path_lower.endswith(".cjs")
            or path_lower.endswith(".py")
            or path_lower.endswith(".go")
            or path_lower.endswith(".java")
            or path_lower.endswith(".kt")
        );
    }
    return (
        path_lower.endswith(".ts")
        or path_lower.endswith(".js")
        or path_lower.endswith(".tsx")
        or path_lower.endswith(".jsx")
        or path_lower.endswith(".mjs")
        or path_lower.endswith(".cjs")
    );
}

def filter_code_import_paths(
    paths: list[str],
    ecosystem: str = "npm"
) -> list[str] {
    filtered: list[str] = [];
    for path in paths {
        p = str(path);
        if _path_matches_ecosystem(p.lower(), ecosystem) {
            filtered.append(p);
        }
    }
    return filtered;
}

def classify_usage_from_paths(
    package_name: str,
    importing_files: list[str],
    ecosystem: str = "npm"
) -> dict {
    import re;

    importing_files = filter_code_import_paths(importing_files, ecosystem);

    TEST_PATTERNS = [
        r"[/\\]test[s]?[/\\]",
        r"[/\\]spec[s]?[/\\]",
        r"[/\\]__tests__[/\\]",
        r"[/\\]tests[/\\]",
        r"\.test\.[jt]sx?$",
        r"\.spec\.[jt]sx?$",
        r"test_.*\.py$",
        r"[/\\]_test\.go$",
        r"[/\\]e2e[/\\]",
        r"[/\\]cypress[/\\]",
        r"[/\\]jest[/\\]",
        r"[/\\]mocha[/\\]",
    ];

    BUILD_PATTERNS = [
        r"[/\\]scripts[/\\]",
        r"webpack\.config",
        r"rollup\.config",
        r"vite\.config",
        r"babel\.config",
        r"\.eslintrc",
        r"jest\.config",
        r"[/\\]build[/\\]",
        r"[/\\]dist[/\\]",
        r"setup\.py$",
        r"[/\\]cmd[/\\]",
    ];

    if not importing_files {
        return {
            "surface": "unknown",
            "is_prod": False,
            "importing_file_count": 0,
            "importing_files": [],
        };
    }

    test_count = 0;
    build_count = 0;
    prod_count = 0;

    for path in importing_files {
        path_lower = str(path).lower();
        is_test = False;
        is_build = False;
        for pattern in TEST_PATTERNS {
            if re.search(pattern, path_lower) {
                is_test = True;
                break;
            }
        }
        if not is_test {
            for pattern in BUILD_PATTERNS {
                if re.search(pattern, path_lower) {
                    is_build = True;
                    break;
                }
            }
        }
        if is_test {
            test_count += 1;
        } elif is_build {
            build_count += 1;
        } else {
            prod_count += 1;
        }
    }

    total = len(importing_files);

    if prod_count > 0 {
        surface = "production";
        is_prod = True;
    } elif build_count > 0 and test_count == 0 {
        surface = "build";
        is_prod = False;
    } elif test_count > 0 and prod_count == 0 {
        surface = "test";
        is_prod = False;
    } else {
        surface = "mixed";
        is_prod = prod_count > 0;
    }

    return {
        "surface": surface,
        "is_prod": is_prod,
        "importing_file_count": total,
        "importing_files": importing_files[0:6],
        "prod_count": prod_count,
        "test_count": test_count,
        "build_count": build_count,
    };
}

"""Loop primitive — propose remediation for vulnerable packages."""

import from graph.nodes { Package, CVE }

def version_gte(candidate: str, minimum: str) -> bool {
    a_parts = str(candidate).split(".");
    b_parts = str(minimum).split(".");
    idx = 0;
    while idx < len(a_parts) and idx < len(b_parts) {
        a_num = 0;
        b_num = 0;
        try {
            a_num = int(a_parts[idx]);
        } except Exception {
            a_num = 0;
        }
        try {
            b_num = int(b_parts[idx]);
        } except Exception {
            b_num = 0;
        }
        if a_num > b_num {
            return True;
        }
        if a_num < b_num {
            return False;
        }
        idx += 1;
    }
    return len(a_parts) >= len(b_parts);
}

walker RemediationWalker {
    has max_attempts: int = 3;
    has plans: list[dict] = [];

    can remediate with Package entry {
        cve_nodes = [here-->][?:CVE];
        if not cve_nodes {
            disengage;
        }
        fixed = "";
        for cve_node in cve_nodes {
            if cve_node.fixed_version and not fixed {
                fixed = str(cve_node.fixed_version);
            }
        }
        if not fixed {
            disengage;
        }

        attempt = 0;
        chosen = fixed;
        breaking: list[str] = [];
        confidence = 0.9;
        status = "proposed";
        while attempt < self.max_attempts {
            attempt += 1;
            if version_gte(chosen, fixed) {
                status = "validated";
                confidence = 0.9;
                break;
            }
            chosen = fixed;
            confidence = 0.5;
            status = "proposed";
        }

        plan = {
            "event": "remediation_plan",
            "package": here.name,
            "from": here.version,
            "to": chosen,
            "breaking_changes": breaking,
            "confidence": confidence,
            "status": status
        };
        self.plans.append(plan);
        report plan;
        disengage;
    }
}

"""Executive summary generation for investigation results."""

import from models.llm_config { routing_llm }
import from tools.summary_util { sanitize_executive_summary }

"""Write a concise executive summary (markdown) for a dependency security investigation.
Repository: {repo_url}
Packages scanned: {packages_scanned}
Vulnerable packages: {vulnerable_count}

Findings:
{findings_text}

Use short sections with ## headings. Be specific about the highest-risk packages and CVEs.
Write package names as plain text or inline code with backticks only (e.g. `jsonwebtoken@0.4.0`).
Never use markdown links, email links, or mailto: URLs for package names — no [name](url) syntax at all.
Mention exploitability when findings include production usage (e.g. CRITICAL exploitability on prod auth code).
Do not invent CVE IDs or versions not listed in the findings."""
def generate_executive_summary(
    repo_url: str,
    findings_text: str,
    packages_scanned: int,
    vulnerable_count: int
) -> str by llm(
    model=routing_llm,
    temperature=0.2,
    max_tokens=1024
);

def generate_executive_summary_safe(
    repo_url: str,
    findings_text: str,
    packages_scanned: int,
    vulnerable_count: int
) -> str {
    raw = generate_executive_summary(
        repo_url,
        findings_text,
        packages_scanned,
        vulnerable_count
    );
    return sanitize_executive_summary(raw);
}

