// Walker to initialize the graph from the mock JSON file
walker InitGraph {
    can read_file;
    can instantiate;
    do {
        // Load JSON data (mock_cloud_state.json) located in the same directory
        let raw = std::io.read_file("mock_cloud_state.json");
        let data = std::json.parse(raw);
        // Expect data to be an array of objects with type and name
        for obj in data {
            match obj["type"] {
                "ComputeNode" => {
                    let cn = ComputeNode(name=obj["name"]);
                    // For demo purposes we link compute to the security group (if present later)
                }
                "DatabaseNode" => {
                    let db = DatabaseNode(name=obj["name"]);
                }
                "SecurityGroupNode" => {
                    let sg = SecurityGroupNode(
                        name=obj["name"],
                        open_ports=obj["open_ports"]
                    );
                }
                _ => {}
            }
        }
        // Manually create a few edges for the prototype
        // Assume we have one compute node "PaymentGateway" and one DB "LedgerDB"
        let compute = ComputeNode(name="PaymentGateway");
        let db = DatabaseNode(name="LedgerDB");
        let sg = SecurityGroupNode(name="PublicFacingGroup", open_ports=[22, 443]);
        // Dependency from compute to DB
        DependencyEdge(from=compute, to=db, criticality=9, financial_exposure=1000000);
        // Network route from compute to security group
        NetworkRouteEdge(from=compute, to=sg);
        log("[INIT] Graph initialized with mock cloud state");
    }
}

