def:pub queryValue(search: str, key: str) -> str {
    clean: str = search;
    if clean.startswith("?") {
        clean = clean[1:];
    }
    parts: list[str] = clean.split("&");
    for part in parts {
        pair: list[str] = part.split("=");
        if len(pair) > 1 and pair[0] == key {
            return pair[1];
        }
    }
    return "";
}

