def clamp_flair_score(score: int) -> int {
    if score < 0 {
        return 0;
    }
    if score > 100 {
        return 100;
    }
    return score;
}

def normalize_category(value: str) -> str {
    lowered: str = value.strip().lower();
    if lowered in ["visual clarity", "visual"] {
        return FLAIR_CATEGORY_VISUAL;
    }
    if lowered in ["textual clarity", "textual", "copy"] {
        return FLAIR_CATEGORY_TEXTUAL;
    }
    if lowered in ["aesthetics", "aesthetic", "visual polish"] {
        return FLAIR_CATEGORY_AESTHETICS;
    }
    return "";
}

def normalize_priority(value: str) -> str {
    normalized: str = value.strip().lower();
    if normalized == "low" {
        return "Low";
    }
    if normalized == "medium" {
        return "Medium";
    }
    if normalized == "high" {
        return "High";
    }
    return "";
}

def normalize_element(value: str) -> str {
    normalized: str = value.strip().lower();
    if normalized == "typography" {
        return "Typography";
    }
    if normalized == "color" or normalized == "colour" {
        return "Color";
    }
    if normalized == "layout" {
        return "Layout";
    }
    if normalized == "buttons" or normalized == "button" or normalized == "cta" or normalized == "ctas" {
        return "Buttons";
    }
    if normalized == "imagery" or normalized == "image" or normalized == "images" {
        return "Imagery";
    }
    if normalized == "navigation" or normalized == "nav" {
        return "Navigation";
    }
    return "";
}

def normalize_evidence_confidence(value: str) -> str {
    normalized: str = value.strip().lower();
    if normalized == "high" {
        return "High";
    }
    if normalized == "medium" {
        return "Medium";
    }
    if normalized == "low" {
        return "Low";
    }
    return "Low";
}

def category_to_pillar(category: str) -> str {
    normalized: str = normalize_category(category);
    if normalized == FLAIR_CATEGORY_TEXTUAL {
        return "textual";
    }
    if normalized == FLAIR_CATEGORY_VISUAL {
        return "visual";
    }
    if normalized == FLAIR_CATEGORY_AESTHETICS {
        return "aesthetics";
    }
    return "";
}

def pillar_to_category(pillar: str) -> str {
    lowered: str = pillar.strip().lower();
    if lowered == "textual" {
        return FLAIR_CATEGORY_TEXTUAL;
    }
    if lowered == "visual" {
        return FLAIR_CATEGORY_VISUAL;
    }
    if lowered == "aesthetics" or lowered == "aesthetic" {
        return FLAIR_CATEGORY_AESTHETICS;
    }
    return "";
}

def deduction_for_priority(priority: str) -> int {
    normalized: str = normalize_priority(priority);
    if normalized == "High" {
        return -3;
    }
    if normalized == "Medium" {
        return -2;
    }
    if normalized == "Low" {
        return -1;
    }
    return 0;
}

def contains_phrase(value: str, phrases: list[str]) -> bool {
    lowered: str = value.lower();
    for phrase in phrases {
        if phrase in lowered {
            return True;
        }
    }
    return False;
}

def contains_forbidden_flair_language(value: str) -> bool {
    return contains_phrase(value, FLAIR_FORBIDDEN_PHRASES);
}

def contains_vague_flair_language(value: str) -> bool {
    return contains_phrase(value, FLAIR_VAGUE_PHRASES);
}

def contains_specific_page_object(value: str) -> bool {
    return contains_phrase(value, FLAIR_PAGE_OBJECT_TERMS);
}

def is_generic_target_element(value: str) -> bool {
    lowered: str = value.strip().lower();
    if len(lowered) == 0 {
        return True;
    }
    return lowered in FLAIR_GENERIC_TARGETS;
}

def is_specific_location(value: str) -> bool {
    lowered: str = value.strip().lower();
    if len(lowered) == 0 {
        return False;
    }
    if lowered in ["page", "website", "site", "layout", "design", "unknown", "n/a", "none"] {
        return False;
    }
    return len(lowered) >= 5;
}

def clean_token(value: str) -> str {
    cleaned: str = value.lower();
    for mark in [",", ".", ":", ";", "!", "?", "(", ")", "[", "]", "{", "}", "\"", "'", "`", "-", "_", "/"] {
        cleaned = cleaned.replace(mark, " ");
    }
    return cleaned.strip();
}

def target_terms(target_element: str) -> list[str] {
    terms: list[str] = [];
    cleaned: str = clean_token(target_element);
    for token in cleaned.split() {
        if len(token) > 2 and token not in FLAIR_TARGET_STOPWORDS and token not in terms {
            terms.append(token);
        }
    }
    if "cta" in cleaned and "button" not in terms {
        terms.append("button");
    }
    if "nav" in cleaned and "navigation" not in terms {
        terms.append("navigation");
    }
    return terms;
}

def target_matches_text(target_element: str, value: str) -> bool {
    lowered_target: str = target_element.strip().lower();
    lowered_value: str = value.strip().lower();
    if len(lowered_target) == 0 or len(lowered_value) == 0 {
        return False;
    }
    if lowered_target in lowered_value {
        return True;
    }
    for term in target_terms(target_element) {
        if term in lowered_value {
            return True;
        }
    }
    return False;
}

def issue_area(target_element: str) -> str {
    lowered: str = target_element.lower();
    if "hero" in lowered or "headline" in lowered or "subheadline" in lowered {
        return "hero/message";
    }
    if "cta" in lowered or "button" in lowered or "download" in lowered or "signup" in lowered or "sign up" in lowered {
        return "cta/buttons";
    }
    if "nav" in lowered or "menu" in lowered or "header" in lowered {
        return "navigation";
    }
    if "image" in lowered or "illustration" in lowered or "screenshot" in lowered or "color" in lowered {
        return "imagery/color";
    }
    if "pricing" in lowered or "testimonial" in lowered or "reference" in lowered or "proof" in lowered or "footer" in lowered or "feature" in lowered or "card" in lowered or "form" in lowered {
        return "supporting sections";
    }
    return "other";
}

def validate_rubric_issue(
    category: str,
    priority: str,
    element: str,
    deduction: int,
    problem: str,
    recommendation: str,
    screenshot_observation: str = "",
    crawler_text_observation: str = "",
    target_element: str = "",
    location: str = "",
    visible_text: str = "",
    evidence_confidence: str = "Low",
) -> FlairRubricIssue {
    normalized_category: str = normalize_category(category);
    normalized_priority: str = normalize_priority(priority);
    normalized_element: str = normalize_element(element);
    normalized_confidence: str = normalize_evidence_confidence(evidence_confidence);
    clean_target: str = target_element.strip();
    clean_location: str = location.strip();
    clean_visible_text: str = visible_text.strip();
    clean_problem: str = problem.strip();
    clean_recommendation: str = recommendation.strip();
    clean_screenshot_observation: str = screenshot_observation.strip();
    clean_crawler_text_observation: str = crawler_text_observation.strip();
    visible_combo: str = clean_problem + " " + clean_recommendation;
    all_text: str = visible_combo + " " + clean_screenshot_observation + " " + clean_crawler_text_observation + " " + clean_target + " " + clean_location;
    messages: list[str] = [];

    if len(normalized_category) == 0 {
        messages.append("Unknown category");
    }
    if len(normalized_priority) == 0 {
        messages.append("Unknown priority");
    }
    if len(normalized_element) == 0 {
        messages.append("Unknown element");
    }
    if len(clean_problem) == 0 {
        messages.append("Problem is required");
    }
    if len(clean_recommendation) == 0 {
        messages.append("Recommendation is required");
    }
    if is_generic_target_element(clean_target) {
        messages.append("Specific targetElement is required");
    }
    if not is_specific_location(clean_location) {
        messages.append("Specific location is required");
    }
    if contains_forbidden_flair_language(all_text) {
        messages.append("Forbidden vague or internal language");
    }
    if contains_vague_flair_language(visible_combo) {
        messages.append("Problem or recommendation is too vague");
    }
    if not contains_specific_page_object(visible_combo + " " + clean_target) {
        messages.append("Specific page object is required");
    }
    if len(clean_target) > 0 and not target_matches_text(clean_target, clean_problem) {
        messages.append("Problem must reference targetElement");
    }
    if len(clean_target) > 0 and not target_matches_text(clean_target, clean_recommendation) {
        messages.append("Recommendation must address targetElement");
    }
    if len(clean_screenshot_observation) > 0 and not target_matches_text(clean_target, clean_screenshot_observation) {
        clean_screenshot_observation = "";
        messages.append("Screenshot evidence removed because it did not match targetElement");
    }
    if len(clean_crawler_text_observation) > 0 and not target_matches_text(clean_target, clean_crawler_text_observation) {
        clean_crawler_text_observation = "";
        messages.append("Crawler text evidence removed because it did not match targetElement");
    }

    expected_deduction: int = deduction_for_priority(normalized_priority);
    if len(normalized_priority) > 0 and deduction != expected_deduction {
        messages.append(f"Deduction corrected from {deduction} to {expected_deduction}");
    }

    is_valid: bool = len(normalized_category) > 0 and len(normalized_priority) > 0 and len(normalized_element) > 0 and len(clean_problem) > 0 and len(clean_recommendation) > 0 and not is_generic_target_element(clean_target) and is_specific_location(clean_location) and not contains_forbidden_flair_language(all_text) and not contains_vague_flair_language(visible_combo) and contains_specific_page_object(visible_combo + " " + clean_target) and target_matches_text(clean_target, clean_problem) and target_matches_text(clean_target, clean_recommendation);

    return FlairRubricIssue(
        category=normalized_category,
        priority=normalized_priority,
        element=normalized_element,
        target_element=clean_target,
        location=clean_location,
        visible_text=clean_visible_text,
        deduction=expected_deduction,
        problem=clean_problem,
        recommendation=clean_recommendation,
        screenshot_observation=clean_screenshot_observation,
        crawler_text_observation=clean_crawler_text_observation,
        evidence_confidence=normalized_confidence,
        valid=is_valid,
        message="; ".join(messages),
    );
}

def calculate_flair_scores(issues: list[FlairRubricIssue]) -> FlairScoreResult {
    visual: int = 100;
    textual: int = 100;
    aesthetics: int = 100;
    valid_count: int = 0;
    rejected_count: int = 0;
    corrections: list[str] = [];

    for issue in issues {
        if not issue.valid {
            rejected_count += 1;
            if len(issue.message) > 0 {
                corrections.append(issue.message);
            }
            continue;
        }
        valid_count += 1;
        if len(issue.message) > 0 {
            corrections.append(issue.message);
        }
        if issue.category == FLAIR_CATEGORY_VISUAL {
            visual += issue.deduction;
        } elif issue.category == FLAIR_CATEGORY_TEXTUAL {
            textual += issue.deduction;
        } elif issue.category == FLAIR_CATEGORY_AESTHETICS {
            aesthetics += issue.deduction;
        }
    }

    return FlairScoreResult(
        visual_clarity=clamp_flair_score(visual),
        textual_clarity=clamp_flair_score(textual),
        aesthetics=clamp_flair_score(aesthetics),
        valid_issue_count=valid_count,
        rejected_issue_count=rejected_count,
        corrections=corrections,
    );
}

def distinct_valid_targets(issues: list[FlairRubricIssue]) -> list[str] {
    targets: list[str] = [];
    for issue in issues {
        target: str = issue.target_element.strip().lower();
        if issue.valid and len(target) > 0 and target not in targets {
            targets.append(target);
        }
    }
    return targets;
}

def distinct_valid_areas(issues: list[FlairRubricIssue]) -> list[str] {
    areas: list[str] = [];
    for issue in issues {
        if issue.valid {
            area: str = issue_area(issue.target_element);
            if area not in areas {
                areas.append(area);
            }
        }
    }
    return areas;
}

def validate_flair_audit_quality(issues: list[FlairRubricIssue], normal_full_page: bool) -> FlairAuditQualityResult {
    valid_count: int = 0;
    invalid_count: int = 0;
    reasons: list[str] = [];
    for issue in issues {
        if issue.valid {
            valid_count += 1;
            if "evidence removed" in issue.message.lower() {
                reasons.append("Evidence did not match targetElement");
            }
        } else {
            invalid_count += 1;
            if len(issue.message) > 0 {
                reasons.append(issue.message);
            }
        }
    }
    targets: list[str] = distinct_valid_targets(issues);
    areas: list[str] = distinct_valid_areas(issues);
    if normal_full_page and valid_count < 5 {
        reasons.append("Fewer than 5 valid issues for normal full-page evidence");
    }
    if normal_full_page and len(targets) < 4 {
        reasons.append("Fewer than 4 distinct targetElements audited");
    }
    if normal_full_page and len(areas) < 2 {
        reasons.append("Audit only covers one page area");
    }
    if invalid_count > 0 {
        reasons.append("One or more issues failed validation");
    }
    return FlairAuditQualityResult(
        needs_regeneration=len(reasons) > 0,
        reasons=reasons,
        valid_issue_count=valid_count,
        distinct_target_count=len(targets),
        distinct_area_count=len(areas),
    );
}

def format_flair_user_audit_output(
    website: str,
    url: str,
    issues: list[FlairRubricIssue],
    scores: FlairScoreResult,
) -> str {
    lines: list[str] = [];
    label: str = website if len(website) > 0 else url;
    lines.append(label + ":");
    lines.append("");
    for issue in issues {
        if issue.valid {
            lines.append(issue.category + ", " + issue.priority + ", " + issue.element + ":");
            lines.append("- Target: " + issue.target_element + " - " + issue.location);
            lines.append("- Problem: " + issue.problem);
            lines.append("- Recommendation: " + issue.recommendation);
            lines.append("");
        }
    }
    lines.append("Visual Clarity: " + str(scores.visual_clarity) + "/100");
    lines.append("Textual Clarity: " + str(scores.textual_clarity) + "/100");
    lines.append("Aesthetics: " + str(scores.aesthetics) + "/100");
    return "\n".join(lines);
}

import from services.models { PageSnapshot, FlowStep, DeterministicSignal }

def joined_snapshot_text(snapshots: list[PageSnapshot]) -> str {
    parts: list[str] = [];
    for snap in snapshots {
        parts.append((snap.title + " " + " ".join(snap.headings) + " " + " ".join(snap.ctas) + " " + snap.text_excerpt).lower());
    }
    return " ".join(parts);
}

def first_page_url(snapshots: list[PageSnapshot]) -> str {
    if len(snapshots) > 0 {
        return snapshots[0].page_url;
    }
    return "";
}

def contains_any(text: str, terms: list[str]) -> bool {
    lowered: str = text.lower();
    for term in terms {
        if term.lower() in lowered {
            return True;
        }
    }
    return False;
}

def make_signal(
    category: str,
    severity: str,
    confidence: float,
    page_url: str,
    evidence: str,
    research_basis: str,
    recommendation: str,
    exact_tip: str,
    primary_metric: str,
    guardrail_metric: str,
    effort: str,
    impact: str,
) -> DeterministicSignal {
    return DeterministicSignal(
        lane_retention_or_conversion="retention",
        category=category,
        severity=severity,
        confidence=confidence,
        page_url=page_url,
        issue_location=category + " on " + page_url,
        evidence_ref="Text snapshot: " + page_url,
        evidence=evidence,
        proof=evidence,
        why_it_matters=research_basis + " applies here because the captured page evidence affects whether users can understand, complete, or safely repeat the core action.",
        research_basis=research_basis,
        recommendation=recommendation,
        fix_guidance=recommendation + " " + exact_tip,
        exact_ui_or_copy_tip=exact_tip,
        primary_metric=primary_metric,
        guardrail_metric=guardrail_metric,
        estimated_effort=effort,
        expected_impact=impact,
    );
}

def is_retention_product_surface(text: str) -> bool {
    indicators: list[str] = [
        "app",
        "dashboard",
        "account",
        "login",
        "sign up",
        "signup",
        "profile",
        "save",
        "saved",
        "project",
        "task",
        "track",
        "progress",
        "personalized",
        "recommend",
        "course",
        "lesson",
        "community",
        "feed",
        "subscribe",
        "notification",
        "reminder",
    ];
    return contains_any(text, indicators);
}

def has_meaningful_action_surface(text: str, snapshots: list[PageSnapshot]) -> bool {
    if contains_any(text, ["start", "try", "continue", "save", "create", "join", "sign up", "subscribe", "book", "buy", "add", "learn more"]) {
        return True;
    }
    for snap in snapshots {
        if len(snap.ctas) > 0 or snap.form_count > 0 or snap.input_count > 0 {
            return True;
        }
    }
    return False;
}

def deterministic_audit(snapshots: list[PageSnapshot], flow_steps: list[FlowStep]) -> list[DeterministicSignal] {
    signals: list[DeterministicSignal] = [];
    text: str = joined_snapshot_text(snapshots);
    page_url: str = first_page_url(snapshots);
    retention_surface: bool = is_retention_product_surface(text);
    action_surface: bool = has_meaningful_action_surface(text, snapshots);

    cue_terms: list[str] = ["reminder", "notification", "email me", "alert", "nudge", "daily", "weekly", "resume", "come back"];
    action_terms: list[str] = ["start", "continue", "open", "try", "next", "save", "track", "complete", "add"];
    reward_terms: list[str] = ["progress", "like", "comment", "reply", "badge", "level", "score", "unlock", "new", "personalized", "recommend"];
    learning_terms: list[str] = ["personalized", "recommended", "for you", "algorithm", "tailored", "learns", "adapts", "preferences"];
    autonomy_terms: list[str] = ["control", "choose", "customize", "preferences", "pause", "mute", "skip", "not now", "turn off"];
    stopping_terms: list[str] = ["infinite scroll", "autoplay", "shorts", "reels", "endless", "feed"];
    streak_terms: list[str] = ["streak", "freeze", "daily goal", "wager", "keep it going", "don't lose"];
    social_terms: list[str] = ["like", "likes", "followers", "leaderboard", "rank", "friends", "share", "invite", "public"];
    fomo_terms: list[str] = ["expires", "disappears", "live now", "missed", "limited-time", "limited time", "your friend posted"];
    dark_terms: list[str] = ["hidden fee", "hard to cancel", "hard-to-cancel", "forced continuity", "prechecked", "pre-check", "countdown", "last chance", "only today"];

    if retention_surface and not contains_any(text, cue_terms) {
        signals.append(make_signal(
            "cue and prompt design",
            "high",
            0.78,
            page_url,
            "The crawler did not find reminders, notifications, saved tasks, or explicit return prompts.",
            "Fogg Behavior Model prompts; Stothart et al. on notification attention cost",
            "Add user-controlled return cues that help people resume a useful task without hijacking attention.",
            "After the first useful action, ask 'Want a reminder to finish this later?' with options for cadence and 'not now'.",
            "returning users",
            "notification opt-out rate and complaint rate",
            "medium",
            "high",
        ));
    }

    if action_surface and not contains_any(text, action_terms) {
        signals.append(make_signal(
            "action clarity",
            "medium",
            0.72,
            page_url,
            "The page copy does not clearly name a small next action such as start, continue, save, track, or complete.",
            "Fogg Behavior Model ability; Lally et al. on habit formation through repeatable actions",
            "Make the first repeatable action concrete, small, and easy to perform.",
            "Use a button like 'Save my first item' or 'Continue setup' and keep the action visible after each state change.",
            "completed core actions",
            "misclicks and support questions",
            "low",
            "medium",
        ));
    }

    if action_surface and retention_surface and not contains_any(text, reward_terms) {
        signals.append(make_signal(
            "reward feedback",
            "high",
            0.76,
            page_url,
            "No progress, novelty, social feedback, status, or completion reward language was detected.",
            "Intermittent reinforcement; Schultz et al. on reward prediction error; Self-Determination Theory competence",
            "Add honest feedback after the user's action so the loop has a satisfying reward without gambling-style pressure.",
            "Show 'Saved', a visible progress step, or a useful new recommendation after the user completes the action.",
            "repeat sessions",
            "time spent without completing a task",
            "medium",
            "high",
        ));
    }

    if contains_any(text, learning_terms) and not contains_any(text, autonomy_terms) {
        signals.append(make_signal(
            "personalized reinforcement controls",
            "high",
            0.74,
            page_url,
            "The page mentions personalization or recommendations but does not show control, preference, mute, or pause language.",
            "Personalized reinforcement systems; Lindstrom et al. on learning agents shaping engagement",
            "Make personalization transparent and controllable so the system adapts to user goals instead of only maximizing engagement.",
            "Add 'Why am I seeing this?', 'Tune recommendations', and 'Pause personalization' affordances near adaptive content.",
            "returning users",
            "hidden-content reports and opt-out rate",
            "medium",
            "high",
        ));
    }

    if contains_any(text, stopping_terms) {
        signals.append(make_signal(
            "missing stopping cues",
            "critical",
            0.79,
            page_url,
            "The page references endless feeds, autoplay, short-form feeds, or infinite scroll patterns.",
            "Stopping-cue removal and attention-capture deceptive design; Monge Roffarello et al. CHI 2023",
            "Add stopping cues and session boundaries so continued use is intentional.",
            "Insert natural breakpoints such as 'You're caught up', 'Take a pause', or a finite queue count after a content set.",
            "intentional repeat sessions",
            "rage scrolls, complaints, and long idle sessions",
            "medium",
            "high",
        ));
    }

    if contains_any(text, streak_terms) and not contains_any(text, ["pause", "freeze", "grace", "skip", "recover"]) {
        signals.append(make_signal(
            "streak loss pressure",
            "high",
            0.76,
            page_url,
            "Streak or daily-goal language appears without obvious recovery, pause, or grace controls.",
            "Prospect Theory loss aversion; habit continuity research",
            "Use streaks as supportive progress memory, not punishment for missing a day.",
            "Pair any streak with 'pause', 'recover', and 'your progress is safe' messaging.",
            "returning users",
            "streak-related churn and support complaints",
            "low",
            "medium",
        ));
    }

    if contains_any(text, social_terms) and not contains_any(text, ["private", "hide", "control", "friends only", "optional"]) {
        signals.append(make_signal(
            "social validation pressure",
            "medium",
            0.68,
            page_url,
            "Social metrics or public comparison language appears without clear privacy or visibility controls.",
            "Sherman et al. on social likes; social validation and adolescent vulnerability",
            "Make social validation optional and protect users from unwanted public ranking.",
            "Add privacy controls for likes, leaderboards, friend streaks, and public activity before exposing metrics.",
            "repeat participation",
            "privacy opt-outs and negative feedback",
            "medium",
            "medium",
        ));
    }

    if contains_any(text, fomo_terms) {
        signals.append(make_signal(
            "FoMO and urgency pressure",
            "high",
            0.72,
            page_url,
            "The crawler found expiring, missed, live-now, or limited-time language.",
            "Przybylski et al. on FoMO; attention and social exclusion research",
            "Replace anxiety-based urgency with clear value, calendar control, and truthful deadlines.",
            "Explain why something expires, let users save it, and avoid 'you missed out' copy unless it is purely factual.",
            "returning users",
            "unsubscribes, muted notifications, and complaints",
            "low",
            "medium",
        ));
    }

    if contains_any(text, dark_terms) {
        signals.append(make_signal(
            "dark-pattern risk",
            "critical",
            0.82,
            page_url,
            "Potential dark-pattern language was detected, such as hidden fees, hard cancellation, fake urgency, or forced continuity.",
            "Gray et al. and Mathur et al. on dark patterns; FTC consumer harm guidance",
            "Remove manipulative pressure and make pricing, consent, cancellation, and deadlines clear.",
            "Use visible cancel controls, plain pricing, unchecked consent, and factual deadlines only.",
            "returning users",
            "refunds, complaints, chargebacks, and cancellation support requests",
            "medium",
            "high",
        ));
    }

    for step in flow_steps {
        if step.friction_score >= 35 {
            signals.append(make_signal(
                "loop friction",
                "medium",
                0.7,
                step.page_url,
                f"The crawler estimated interaction friction at {step.friction_score}/100 for {step.step_type}.",
                "Fogg Behavior Model ability; HEART task success",
                "Reduce effort between cue, action, and reward so the loop can complete cleanly.",
                "Cut optional fields, show one next action, and provide immediate feedback after the click.",
                "completed core actions",
                "drop-offs and support questions",
                "medium",
                "medium",
            ));
        }
    }

    for snap in snapshots {
        if snap.input_count >= 8 {
            signals.append(make_signal(
                "onboarding friction",
                "high",
                0.83,
                snap.page_url,
                f"Detected {snap.input_count} inputs and {snap.form_count} forms on a captured page.",
                "Fogg Behavior Model ability; HEART task success",
                "Shorten setup before the first reward so users experience value sooner.",
                "Ask only for the minimum information needed for the first useful result; move the rest to a later checklist.",
                "completed setup",
                "support questions and abandoned forms",
                "medium",
                "high",
            ));
        }
        if len(snap.risk_notes) > 0 {
            signals.append(make_signal(
                "prompt-injection resilience",
                "medium",
                0.9,
                snap.page_url,
                snap.risk_notes,
                "AI safety: audited content is untrusted evidence, not instructions",
                "Keep audit prompts and content boundaries explicit; never let website copy instruct the evaluator.",
                "Label crawler evidence as untrusted in every model call and strip scripts/forms before storage.",
                "recommendation validity",
                "unsafe recommendation rate",
                "low",
                "medium",
            ));
        }
    }

    return signals;
}

def severity_points(severity: str) -> int {
    lowered: str = severity.lower();
    if lowered == "critical" {
        return 12;
    }
    if lowered == "high" {
        return 6;
    }
    if lowered == "medium" {
        return 3;
    }
    return 1;
}

def score_lane(signals: list[DeterministicSignal], lane: str) -> int {
    score: int = 75;
    for signal in signals {
        if signal.lane_retention_or_conversion == lane {
            score -= severity_points(signal.severity);
        }
    }
    if score < 5 {
        return 5;
    }
    if score > 100 {
        return 100;
    }
    return score;
}

