import from "@jac/runtime" { jacLogin, jacSignup, useNavigate }

def:pub page() -> JsxElement {
    has is_login: bool = True;
    has username: str = "";
    has password: str = "";
    has error: str = "";
    has loading: bool = False;

    navigate = useNavigate();

    async def handle_submit(e: FormEvent) -> None {
        e.preventDefault();
        loading = True;
        error = "";
        try {
            if is_login {
                login_res = await jacLogin(username, password);
                if login_res {
                    navigate("/dashboard");
                } else {
                    error = "Invalid credentials. Try demo / demo123";
                }
            } else {
                signup_res = await jacSignup(username, password);
                if signup_res {
                    login_after = await jacLogin(username, password);
                    if login_after {
                        navigate("/dashboard");
                    } else {
                        error = "Account created — please sign in";
                    }
                } else {
                    error = "Signup failed. Username may already be taken.";
                }
            }
        } except Exception as ex {
            error = "Authentication error. Please try again.";
        }
        loading = False;
    }

    def handle_username(e: ChangeEvent) -> None {
        username = e.target.value;
    }

    def handle_password(e: ChangeEvent) -> None {
        password = e.target.value;
    }

    def toggle_mode(e: MouseEvent) -> None {
        is_login = not is_login;
        error = "";
    }

    return (
        <div className="min-h-screen bg-background grid-bg flex items-center justify-center relative overflow-hidden">
            <div style={{"position": "absolute", "top": "10%", "left": "20%", "width": "400px", "height": "400px", "background": "radial-gradient(circle, rgba(59,130,246,0.08) 0%, transparent 70%)", "pointerEvents": "none"}}></div>
            <div style={{"position": "absolute", "bottom": "10%", "right": "20%", "width": "300px", "height": "300px", "background": "radial-gradient(circle, rgba(139,92,246,0.06) 0%, transparent 70%)", "pointerEvents": "none"}}></div>

            <div className="w-full max-w-md px-6 animate-fade-in-up">
                <div className="text-center mb-10">
                    <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl mb-4 animate-pulse-glow" style={{"background": "linear-gradient(135deg, rgba(59,130,246,0.2), rgba(139,92,246,0.2))", "border": "1px solid rgba(59,130,246,0.3)"}}>
                        <span style={{"fontSize": "28px"}}>⚡</span>
                    </div>
                    <h1 className="text-3xl font-bold text-gradient-blue mb-2">FutureOS</h1>
                    <p className="text-muted-foreground text-sm">Your Adaptive AI Life Operating System</p>
                </div>

                <div className="glass-bright p-8">
                    <div className="mb-6">
                        <h2 className="text-xl font-semibold text-foreground mb-1">
                            {"Welcome back" if is_login else "Begin your journey"}
                        </h2>
                        <p className="text-muted-foreground text-sm">
                            {"Sign in to your AI workspace" if is_login else "Create your AI-powered life OS"}
                        </p>
                    </div>

                    {error and (
                        <div className="error-box mb-5">{error}</div>
                    )}

                    <form onSubmit={handle_submit}>
                        <div className="mb-4">
                            <label className="label">Username</label>
                            <input
                                className="input"
                                type="text"
                                value={username}
                                onChange={handle_username}
                                placeholder="Enter your username"
                                required={True}
                            />
                        </div>
                        <div className="mb-6">
                            <label className="label">Password</label>
                            <input
                                className="input"
                                type="password"
                                value={password}
                                onChange={handle_password}
                                placeholder="Enter your password"
                                required={True}
                            />
                        </div>

                        <button
                            type="submit"
                            className="btn btn-primary w-full py-3 text-base"
                            disabled={loading}
                        >
                            {loading and (
                                <span className="flex items-center gap-2 justify-center">
                                    <span className="typing-dot"></span>
                                    <span className="typing-dot"></span>
                                    <span className="typing-dot"></span>
                                    <span>{"Authenticating..."}</span>
                                </span>
                            )}
                            {not loading and (
                                <span>{"Sign In" if is_login else "Create Account"}</span>
                            )}
                        </button>
                    </form>

                    <div className="mt-6 text-center">
                        <span className="text-muted-foreground text-sm">
                            {"Don't have an account? " if is_login else "Already have an account? "}
                        </span>
                        <button
                            className="text-primary text-sm font-medium hover:text-blue-400 transition-colors"
                            onClick={toggle_mode}
                        >
                            {"Sign up" if is_login else "Sign in"}
                        </button>
                    </div>
                </div>

                <div className="mt-8 grid grid-cols-3 gap-3">
                    <div className="text-center p-3 rounded-xl" style={{"background": "rgba(59,130,246,0.05)", "border": "1px solid rgba(59,130,246,0.1)"}}>
                        <div className="text-lg mb-1">🤖</div>
                        <div className="text-xs text-muted-foreground">6 AI Agents</div>
                    </div>
                    <div className="text-center p-3 rounded-xl" style={{"background": "rgba(139,92,246,0.05)", "border": "1px solid rgba(139,92,246,0.1)"}}>
                        <div className="text-lg mb-1">🧠</div>
                        <div className="text-xs text-muted-foreground">Memory OS</div>
                    </div>
                    <div className="text-center p-3 rounded-xl" style={{"background": "rgba(6,182,212,0.05)", "border": "1px solid rgba(6,182,212,0.1)"}}>
                        <div className="text-lg mb-1">⚡</div>
                        <div className="text-xs text-muted-foreground">Daily Missions</div>
                    </div>
                </div>
            </div>
        </div>
    );
}

import from "@jac/runtime" { useNavigate, jacIsLoggedIn, Navigate }
import from ..components.Sidebar { Sidebar }
sv import from ..services.appService { MemoryEntry, get_memories, add_memory }

def:pub page() -> JsxElement {
    has memories: list[MemoryEntry] = [];
    has loading: bool = True;
    has show_add: bool = False;
    has saving: bool = False;
    has error: str = "";
    has new_summary: str = "";
    has new_tags: str = "";
    has new_focus: str = "80";
    has new_duration: str = "1h";

    navigate = useNavigate();

    if not jacIsLoggedIn() {
        return <Navigate to="/login" replace={True} />;
    }

    async can with entry {
        if jacIsLoggedIn() {
            try {
                memories = await get_memories();
            } except Exception as ex {
                error = "Failed to load memories";
            }
            loading = False;
        }
    }

    async def do_toggle_add() -> None {
        memories = await get_memories();
        show_add = not show_add;
        error = "";
    }

    async def do_cancel_add() -> None {
        memories = await get_memories();
        show_add = False;
    }

    def toggle_add(e: MouseEvent) -> None {
        do_toggle_add();
    }

    def cancel_add(e: MouseEvent) -> None {
        do_cancel_add();
    }

    def handle_summary(e: ChangeEvent) -> None {
        new_summary = e.target.value;
    }

    def handle_tags(e: ChangeEvent) -> None {
        new_tags = e.target.value;
    }

    def handle_focus(e: ChangeEvent) -> None {
        new_focus = e.target.value;
    }

    def handle_duration(e: ChangeEvent) -> None {
        new_duration = e.target.value;
    }

    async def handle_add(e: FormEvent) -> None {
        e.preventDefault();
        saving = True;
        error = "";
        focus_val: int = 80;
        try {
            focus_val = int(new_focus);
        } except Exception as ex {
            focus_val = 80;
        }
        try {
            summary: str = new_summary;
            tags: str = new_tags;
            focus_score: int = focus_val;
            duration: str = new_duration;
            entry = await add_memory(summary, tags, focus_score, duration);
            memories = [entry] + memories;
            new_summary = "";
            new_tags = "";
            new_focus = "80";
            new_duration = "1h";
            show_add = False;
        } except Exception as ex {
            error = "Failed to save session: " + str(ex);
        }
        saving = False;
    }

    avg_focus: int = 0;
    if len(memories) > 0 {
        total_f: int = 0;
        for m in memories {
            total_f = total_f + m.focus_score;
        }
        avg_focus = total_f // len(memories);
    }

    return (
        <div className="page">
            <Sidebar />
            <div className="page-content">
                <div className="page-header">
                    <div>
                        <h1 className="text-2xl font-bold text-foreground">Memory Timeline</h1>
                        <p className="text-muted-foreground text-sm mt-1">AI-indexed learning history — auto-logged when you complete missions</p>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="badge-cyan">
                            <span>🧠</span>
                            <span>{str(len(memories)) + " sessions indexed"}</span>
                        </div>
                        <button className="btn btn-primary" onClick={toggle_add}>+ Log Session</button>
                    </div>
                </div>

                {error and <div className="error-box mb-4">{error}</div>}

                {show_add and (
                    <div className="card p-6 mb-6" style={{"border": "1px solid rgba(6,182,212,0.3)"}}>
                        <h2 className="text-base font-semibold text-foreground mb-4">Log a Session</h2>
                        <form onSubmit={handle_add}>
                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div className="col-span-2">
                                    <label className="label">What did you work on?</label>
                                    <input className="input" type="text" value={new_summary} onChange={handle_summary} placeholder="e.g. Solved 3 LeetCode problems, studied neural networks" />
                                </div>
                                <div>
                                    <label className="label">Tags (comma-separated)</label>
                                    <input className="input" type="text" value={new_tags} onChange={handle_tags} placeholder="DSA, ML, Python" />
                                </div>
                                <div>
                                    <label className="label">Duration</label>
                                    <input className="input" type="text" value={new_duration} onChange={handle_duration} placeholder="e.g. 2h 30m" />
                                </div>
                                <div>
                                    <label className="label">Focus Score (0-100)</label>
                                    <input className="input" type="number" value={new_focus} onChange={handle_focus} placeholder="80" />
                                </div>
                            </div>
                            <div className="flex gap-3">
                                <button type="submit" className="btn btn-primary" disabled={saving}>
                                    {saving and "Saving..." or "Save Session"}
                                </button>
                                <button type="button" className="btn btn-ghost" onClick={cancel_add}>Cancel</button>
                            </div>
                        </form>
                    </div>
                )}

                {loading and (
                    <div className="flex items-center justify-center py-20">
                        <div className="text-center">
                            <div className="flex gap-2 justify-center mb-3">
                                <span className="typing-dot"></span>
                                <span className="typing-dot"></span>
                                <span className="typing-dot"></span>
                            </div>
                            <p className="text-muted-foreground text-sm">Memory Agent loading sessions...</p>
                        </div>
                    </div>
                )}

                {not loading and len(memories) == 0 and not show_add and (
                    <div className="card p-12 text-center">
                        <div className="text-5xl mb-4">🧠</div>
                        <h2 className="text-xl font-semibold text-foreground mb-2">Memory is empty</h2>
                        <p className="text-muted-foreground text-sm mb-2">Sessions are auto-logged when you complete missions.</p>
                        <p className="text-muted-foreground text-sm mb-6">Or log a session manually.</p>
                        <button className="btn btn-primary" onClick={toggle_add}>+ Log Your First Session</button>
                    </div>
                )}

                {not loading and len(memories) > 0 and (
                    <div className="grid grid-cols-3 gap-6">
                        <div className="col-span-2">
                            <h2 className="text-base font-semibold text-foreground mb-4">Session History</h2>
                            <div className="relative">
                                <div className="absolute left-4 top-0 bottom-0 w-px" style={{"background": "rgba(6,182,212,0.2)"}}></div>
                                <div className="flex flex-col gap-4">
                                    {[
                                        <div key={jid(memories[i])} className="flex items-start gap-4 pl-10 relative">
                                            <div className="absolute left-2.5 w-3 h-3 rounded-full border-2" style={{"top": "16px", "background": "#06b6d4", "borderColor": "#06b6d4"}}></div>
                                            <div className="flex-1 card p-4">
                                                <div className="flex items-start justify-between mb-2">
                                                    <div className="flex-1">
                                                        <div className="text-sm font-medium text-foreground">{memories[i].summary}</div>
                                                        <div className="text-xs text-muted-foreground mt-0.5">{memories[i].duration}</div>
                                                    </div>
                                                    <div className="text-right ml-4">
                                                        <div className="text-sm font-bold" style={{"color": "#06b6d4"}}>{str(memories[i].focus_score) + "%"}</div>
                                                        <div className="text-xs text-muted-foreground">focus</div>
                                                    </div>
                                                </div>
                                                {memories[i].tags and (
                                                    <div className="flex gap-1 flex-wrap">
                                                        {[
                                                            <span key={str(j)} className="badge-cyan text-xs">{tag.strip()}</span>
                                                            for (j, tag) in enumerate(str(memories[i].tags).split(","))
                                                            if tag.strip()
                                                        ]}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        for i in range(len(memories))
                                    ]}
                                </div>
                            </div>
                        </div>

                        <div>
                            <div className="card p-5">
                                <h2 className="text-base font-semibold text-foreground mb-4">Memory Stats</h2>
                                <div className="flex flex-col gap-4">
                                    <div>
                                        <div className="text-xs text-muted-foreground mb-1">Total Sessions</div>
                                        <div className="text-2xl font-bold text-gradient-blue">{str(len(memories))}</div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-muted-foreground mb-1">Avg Focus Score</div>
                                        <div className="text-2xl font-bold" style={{"color": "#06b6d4"}}>{str(avg_focus) + "%"}</div>
                                        <div className="progress-bar mt-1">
                                            <div className="progress-fill" style={{"width": str(avg_focus) + "%"}}></div>
                                        </div>
                                    </div>
                                    <div className="p-3 rounded-xl" style={{"background": "rgba(6,182,212,0.05)", "border": "1px solid rgba(6,182,212,0.1)"}}>
                                        <div className="text-xs font-medium mb-1" style={{"color": "#22d3ee"}}>🧠 Memory Agent</div>
                                        <p className="text-xs text-muted-foreground">Auto-logs every completed mission. Building your learning history.</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

import from "@jac/runtime" { useNavigate, jacIsLoggedIn, Navigate }
import from ..components.Sidebar { Sidebar }
sv import from ..services.appService { Goal, OpportunityReport, get_goals, agent_get_opportunities }

def:pub page() -> JsxElement {
    has active_tab: str = "internships";
    has goals: list[Goal] = [];
    has opportunities: OpportunityReport | None = None;
    has loading: bool = True;
    has generating: bool = False;
    has error: str = "";

    navigate = useNavigate();

    if not jacIsLoggedIn() {
        return <Navigate to="/login" replace={True} />;
    }

    async can with entry {
        if jacIsLoggedIn() {
            try {
                goals = await get_goals();
                if len(goals) > 0 {
                    first_id: str = jid(goals[0]);
                    opportunities = await agent_get_opportunities(first_id);
                }
            } except Exception as ex {
                error = "Failed to load opportunities";
            }
            loading = False;
        }
    }

    async def do_set_internships() -> None {
        goals = await get_goals();
        active_tab = "internships";
    }

    async def do_set_courses() -> None {
        goals = await get_goals();
        active_tab = "courses";
    }

    async def do_set_projects() -> None {
        goals = await get_goals();
        active_tab = "projects";
    }

    async def do_set_networking() -> None {
        goals = await get_goals();
        active_tab = "networking";
