}

def:priv add_goal(title: str, description: str, timeline: str) -> Goal {
    g = (root ++> Goal(title=title, description=description, timeline=timeline, status="active", progress=0, created_at="now"))[0];
    log_agent("Planner", "New goal created", title);
    log_agent("Memory", "Goal indexed in memory", title);
    return g;
}

def:priv update_goal_progress(goal_id: str, progress: int) -> Goal | None {
    for g in [root -->][?:Goal] {
        if jid(g) == goal_id {
            g.progress = progress;
            log_agent("Analytics", "Progress updated to " + str(progress) + "%", g.title);
            if progress >= 100 {
                log_agent("Coach", "Goal completed! Celebrating achievement", g.title);
            } elif progress >= 75 {
                log_agent("Coach", "75%+ reached — final push mode activated", g.title);
            }
            return g;
        }
    }
    return None;
}

def:priv delete_goal(goal_id: str) -> bool {
    for g in [root -->][?:Goal] {
        if jid(g) == goal_id {
            log_agent("Planner", "Goal removed from roadmap", g.title);
            del g;
            return True;
        }
    }
    return False;
}

