import:jac from .models, Executive, SystemMetrics, Crisis, IntelligenceReport, ExecutiveStatus, Severity;
import:py from jaclang.core.utils, log;
import:py from datetime, datetime;

# -----------------------------------------------------------------------------
# AI Brain (MTP)
# -----------------------------------------------------------------------------

can generate_executive_response(crisis: str, role: str) -> str by llm(
    temperature=0.7,
    instruction="As the {role} in an AI command center, provide a strategic response to the following crisis: {crisis}. Keep it professional, data-driven, and under 50 words."
);

can generate_final_report(responses: list[str], crisis: str) -> IntelligenceReport by llm(
    instruction="Synthesize the following executive responses regarding the crisis '{crisis}' into a final Intelligence Report. Responses: {responses}. Ensure the report includes a summary, operational risk (Low/Elevated/High), infrastructure status, and actionable recommendations."
);

# -----------------------------------------------------------------------------
# Public API Functions
# -----------------------------------------------------------------------------

def:pub get_executives() -> list[Executive] {
    return [-->](node::Executive);
}

def:pub get_system_metrics() -> SystemMetrics {
    return [-->](node::SystemMetrics)[0];
}

def:pub trigger_orchestration(crisis_msg: str) {
    spawn root walking OrchestrateCrisis(crisis_msg=crisis_msg);
}

# -----------------------------------------------------------------------------
# Walkers
# -----------------------------------------------------------------------------

walker OrchestrateCrisis {
    has crisis_msg: str;
    has responses: list[str] = [];

    can enter_crisis with `root entry {
        spawn here ++> Crisis(
            id="crisis_" + datetime.now().strftime("%Y%m%d%H%M%S"),
            severity=Severity.HIGH,
            message=crisis_msg,
            triggered_at=datetime.now().isoformat()
        );
        visit [-->](node::Executive);
    }

    can process_executive with Executive entry {
        here.is_thinking = true;
        here.status = ExecutiveStatus.CRISIS;

        response = generate_executive_response(crisis_msg, here.role);

        here.reasoning = response;
        here.is_thinking = false;
        here.status = ExecutiveStatus.SYNC;

        responses.append(response);
    }

    can finalize with `root exit {
        if (responses.length > 0) {
            report_data = generate_final_report(responses, crisis_msg);
            report_data.generated_at = datetime.now().isoformat();
            spawn here ++> report_data;
            log("Orchestration Complete. Intelligence Report generated.");
        }
    }
}

walker SyncSystemStatus {
    can update_metrics with SystemMetrics entry {
        here.uptime_seconds += 5;
        here.system_load = 20.0 + (datetime.now().second % 30);
        here.net_latency = 10 + (datetime.now().second % 15);
    }

    can update_executive with Executive entry {
        if (here.status != ExecutiveStatus.CRISIS) {
            here.workflow_load = (here.workflow_load + 2.5) % 100;
            here.confidence = 95.0 + (here.workflow_load / 50.0);
        }
    }
}

# -----------------------------------------------------------------------------
# Initialization
# -----------------------------------------------------------------------------

def initialize_graph() {
    # Only spawn if they don't exist (persistence check)
    if (not [-->](node::Executive)) {
        spawn root ++> Executive(id="ceo", name="Aura", role="CEO", color="white");
        spawn root ++> Executive(id="cto", name="Nexus", role="CTO", color="cyan");
        spawn root ++> Executive(id="mkt", name="Vibe", role="Marketing", color="violet");
        spawn root ++> Executive(id="hr", name="Pulse", role="HR", color="green");
        spawn root ++> Executive(id="ops", name="Vector", role="Operations", color="orange");
        spawn root ++> Executive(id="sec", name="Aegis", role="Security", color="red");
    }

    if (not [-->](node::SystemMetrics)) {
        spawn root ++> SystemMetrics();
    }
}

