        ranked = clinic_scores(normalized);
        report {
            "ranking_algorithm": {
                "cost_fit": 30,
                "insurance_or_sliding_scale": 20,
                "distance": 15,
                "transportation": 10,
                "language": 10,
                "care_need": 10,
